window.__AtlasPayload=window.__AtlasPayload||{};window.__AtlasPayload["mudlog-cuttings-cls"]={"pkg":{"id":"mudlog-cuttings-cls","sceneId":"m1","methods":["cv"],"title":"白光与荧光双模态岩屑细粒度识别与综合剖面构建","version":"1.0.0","updated":"2026-10-28","tabs":{"background":{"label":"专业背景","lede":"在综合录井作业中，振动筛排出的钻井岩屑是反映井下地层最直观的第一手地质实体。现场地质工需在数分钟内对洗净的岩屑颗粒进行岩性组分百分比（含砂率）估算，并在紫外暗箱下判定原油荧光显示级别，直接决定储层「卡层」时机与取心决策。然而，在实际钻进过程中，**上部未封固井壁崩塌掉落的大块暗色泥岩（Caving）混入样盘**，加之**钻井泥浆对砂岩颗粒的浸染包裹**，使传统目视估算误差极大，主力细砂岩储层常被严重低估漏判。本案例构建了**「标准暗箱双模态采图 → 单颗粒实例分割与泥浆剔除 → 细粒度纹理粒径协同识别 → 365nm 紫外荧光定量定级 → 迟到深度归位与邻深上下文掉块过滤」**五级流水线，实现**单颗粒准确率 92.4%**与**岩性百分比误差（MAE）从 8.6% 降至 1.8%**，精准还原 2452m 油浸级储层真实面貌。","judge":[{"label":"数据形态","value":"双模态显微颗粒图像","desc":"D65 标准白光与 365nm 紫外荧光同视场多颗粒样盘 (36颗/盘)"},{"label":"核心痛点","value":"上部泥岩掉块混淆真储层","desc":"坍塌暗色泥岩混入导致主力砂岩储层含砂率严重被低估 15% 以上"},{"label":"AI 切入点","value":"多任务分割+邻深掉块过滤","desc":"提取粒径/圆度特征与荧光发光面积，结合上下文突变检测剔除掉块"},{"label":"核心收益","value":"组分 MAE 1.8% · 荧光定级","desc":"颗粒准确率 92.4%，油浸级主力储层真实还原，杜绝漏卡储层"}],"sections":[{"no":1,"en":"PROBLEM","title":"当前做法与痛点","html":"<p>随钻录井中，钻头破碎地层产生的岩屑随钻井液沿环空上返至地面振动筛，是地质人员直接观察地下储层性质的最前沿窗口。录井工程师需在极短时间内完成岩性定名与含油性评价：</p>\n<ul>\n  <li><strong>上部井壁掉块（Caving）混入引发严重失真</strong>：当井段穿过易水化膨胀的泥页岩或应力集中层时，上部井壁常发生剥落与坍塌。大块暗色泥岩落入环空与井底新鲜岩屑混合，直接污染样盘。人工肉眼常将掉块当作原位地层，致使高渗透优质砂岩储层的含砂率被严重低估。</li>\n  <li><strong>泥浆滤饼包裹遮蔽微细观纹理</strong>：钻井液中重晶石、聚合物及膨润土牢固包裹颗粒表面，在普通放大镜下难以看清石英、长石晶粒界线与微层理，细砂岩、泥质粉砂与粉砂质泥岩极易混淆。</li>\n  <li><strong>紫外荧光依赖经验估算、缺乏定量标准</strong>：传统点滴荧光与对比色板受照度不均和主观视觉疲劳影响，油斑级与油浸级界限含糊，难以准确判定凝析油与中重质原油类型。</li>\n</ul>\n<div class=\"figure\"><svg viewBox=\"0 0 760 300\" width=\"100%\" role=\"img\" aria-label=\"岩屑录井双模态成像与井筒掉块混入机理\">\n  <rect width=\"760\" height=\"300\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: Wellbore Caving Mechanism -->\n  <rect x=\"14\" y=\"14\" width=\"360\" height=\"272\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"26\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. 钻井环空岩屑携出与上部井壁掉块混入机制</text>\n  <!-- Wellbore -->\n  <rect x=\"80\" y=\"55\" width=\"80\" height=\"190\" fill=\"#e3efec\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n  <rect x=\"110\" y=\"55\" width=\"20\" height=\"190\" fill=\"#424a50\"/>\n  <!-- Upper Caving zone -->\n  <rect x=\"68\" y=\"90\" width=\"12\" height=\"40\" fill=\"#b4483c\" opacity=\"0.6\"/>\n  <rect x=\"160\" y=\"90\" width=\"12\" height=\"40\" fill=\"#b4483c\" opacity=\"0.6\"/>\n  <text x=\"55\" y=\"112\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"end\">上部泥岩坍塌区</text>\n  <!-- Falling big caving rock -->\n  <polygon points=\"90,135 102,130 98,145 88,142\" fill=\"#7d8790\" stroke=\"#b4483c\" stroke-width=\"1.2\"/>\n  <polygon points=\"145,140 155,136 150,152 142,148\" fill=\"#7d8790\" stroke=\"#b4483c\" stroke-width=\"1.2\"/>\n  <text x=\"180\" y=\"146\" font-size=\"8.5\" fill=\"#b4483c\" font-weight=\"700\">大块尖锐掉块 (非原位!)</text>\n  <!-- Bit at bottom -->\n  <rect x=\"100\" y=\"225\" width=\"40\" height=\"20\" rx=\"4\" fill=\"#15191c\"/>\n  <text x=\"100\" y=\"260\" font-size=\"9\" fill=\"#15191c\" font-weight=\"700\">井底 2452m 主力储层</text>\n  <!-- Small true cuttings rising -->\n  <circle cx=\"95\" cy=\"205\" r=\"3\" fill=\"#e0be6e\"/><circle cx=\"145\" cy=\"210\" r=\"3\" fill=\"#e0be6e\"/>\n  <circle cx=\"95\" cy=\"175\" r=\"3\" fill=\"#e0be6e\"/><circle cx=\"145\" cy=\"180\" r=\"3\" fill=\"#e0be6e\"/>\n  <!-- Shaker tray on ground -->\n  <rect x=\"220\" y=\"85\" width=\"140\" height=\"75\" rx=\"5\" fill=\"#fbfaf7\" stroke=\"#3a6ea5\" stroke-width=\"1.4\"/>\n  <text x=\"290\" y=\"105\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">振动筛捞砂样盘</text>\n  <text x=\"290\" y=\"125\" font-size=\"9.5\" fill=\"#c27a2c\" text-anchor=\"middle\">混入 12% 掉块泥岩</text>\n  <text x=\"290\" y=\"145\" font-size=\"8.5\" fill=\"#424a50\" text-anchor=\"middle\">导致储层含砂率由 72% 降至 54%</text>\n\n  <!-- Right: Dual-modal D65 vs UV -->\n  <rect x=\"386\" y=\"14\" width=\"360\" height=\"272\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"398\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. 白光 D65 显微 vs 365nm 紫外荧光双模态对比</text>\n  <!-- Left half: White light -->\n  <rect x=\"402\" y=\"55\" width=\"160\" height=\"185\" rx=\"4\" fill=\"#ebe6da\" stroke=\"#d9d4c8\"/>\n  <text x=\"482\" y=\"74\" font-size=\"10\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">D65 标准白光显微</text>\n  <!-- Grains in white light -->\n  <circle cx=\"445\" cy=\"110\" r=\"14\" fill=\"#e0be6e\" stroke=\"#424a50\"/><text x=\"445\" y=\"114\" font-size=\"8\" fill=\"#15191c\" text-anchor=\"middle\">细砂岩</text>\n  <circle cx=\"510\" cy=\"120\" r=\"12\" fill=\"#c4ba97\" stroke=\"#424a50\"/><text x=\"510\" y=\"124\" font-size=\"8\" fill=\"#15191c\" text-anchor=\"middle\">泥粉砂</text>\n  <polygon points=\"460,160 485,152 480,180 455,175\" fill=\"#7d8790\" stroke=\"#b4483c\" stroke-width=\"1.2\"/>\n  <text x=\"470\" y=\"195\" font-size=\"8\" fill=\"#b4483c\" text-anchor=\"middle\">掉块泥岩</text>\n\n  <!-- Right half: UV 365nm -->\n  <rect x=\"572\" y=\"55\" width=\"160\" height=\"185\" rx=\"4\" fill=\"#0b101b\" stroke=\"#334155\"/>\n  <text x=\"652\" y=\"74\" font-size=\"10\" font-weight=\"700\" fill=\"#38bdf8\" text-anchor=\"middle\">365nm 紫外激发荧光</text>\n  <!-- Glowing grain -->\n  <circle cx=\"615\" cy=\"110\" r=\"14\" fill=\"#111622\" stroke=\"#facc15\" stroke-width=\"1.5\"/>\n  <circle cx=\"615\" cy=\"110\" r=\"10\" fill=\"rgba(250,204,21,0.65)\"/>\n  <text x=\"615\" y=\"114\" font-size=\"7.5\" fill=\"#fff\" font-weight=\"700\" text-anchor=\"middle\">亮黄荧光</text>\n  <!-- Non glowing -->\n  <circle cx=\"680\" cy=\"120\" r=\"12\" fill=\"#111622\" stroke=\"#64748b\"/>\n  <text x=\"680\" y=\"124\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"middle\">弱荧光</text>\n  <!-- Caving no glow -->\n  <polygon points=\"630,160 655,152 650,180 625,175\" fill=\"#111622\" stroke=\"#475569\"/>\n  <text x=\"640\" y=\"195\" font-size=\"7.5\" fill=\"#94a3b8\" text-anchor=\"middle\">无荧光(干泥)</text>\n  <!-- Bottom note -->\n  <rect x=\"402\" y=\"248\" width=\"330\" height=\"26\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"567\" y=\"265\" font-size=\"9\" fill=\"#12615a\" font-weight=\"600\" text-anchor=\"middle\">双模态联合：白光定岩性骨架 + 紫外荧光定含油级别与原油轻重质</text>\n</svg></div>\n<div class=\"figcap\"><b>图 1</b><span>钻井环空岩屑携出与上部井壁掉块混入机理（左）及白光显微与 365nm 紫外荧光双模态成像对比（右）。</span></div>\n<p>为此，智能录井方案必须通过标准化显微暗箱实现物理校色，并利用颗粒几何与邻深地层上下文建立掉块自动剔除机制。</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 215\" width=\"100%\" role=\"img\" aria-label=\"未剔除掉块导致储层低估误差对比\">\n  <rect width=\"760\" height=\"215\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"25\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">传统人工目视录井未剔除上部掉块导致的「储层被低估」误差对比</text>\n  <!-- Box 1 -->\n  <rect x=\"18\" y=\"38\" width=\"350\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"30\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#b4483c\">1. 传统未剔除掉块：主力细砂岩被当成粉砂质泥岩</text>\n  <rect x=\"30\" y=\"70\" width=\"326\" height=\"58\" rx=\"4\" fill=\"#f6e3df\" stroke=\"#b4483c\"/>\n  <text x=\"42\" y=\"92\" font-size=\"10.5\" font-weight=\"700\" fill=\"#b4483c\">2452m 储层段：混入 12% 上覆垮塌泥岩掉块</text>\n  <text x=\"42\" y=\"110\" font-size=\"9.5\" fill=\"#424a50\">统计含砂率仅 54.2%（真实为 72.0%），错失最佳卡层取心时机</text>\n  <text x=\"30\" y=\"152\" font-size=\"10\" fill=\"#b4483c\">× 组分百分比绝对误差 MAE 高达 8.6%</text>\n  <text x=\"30\" y=\"172\" font-size=\"10\" fill=\"#737c83\">× 泥浆包裹污染掩盖真实矿物纹理，人工误判率激增</text>\n\n  <!-- Box 2 -->\n  <rect x=\"392\" y=\"38\" width=\"350\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.3\"/>\n  <text x=\"404\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">2. AI 粒径-圆度分析 + 邻深突变过滤：精准还原</text>\n  <rect x=\"404\" y=\"70\" width=\"326\" height=\"58\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"416\" y=\"92\" font-size=\"10.5\" font-weight=\"700\" fill=\"#12615a\">结合圆度 (0.28 棱角尖锐) 与大粒径特征识别掉块并剔除</text>\n  <text x=\"416\" y=\"110\" font-size=\"9.5\" fill=\"#424a50\">储层细砂岩百分比精准归位至 70.8%，定为油浸级主力层</text>\n  <text x=\"404\" y=\"152\" font-size=\"10\" fill=\"#12615a\" font-weight=\"700\">✓ 岩性组分平均绝对误差 MAE 从 8.6% 降至 1.8%</text>\n  <text x=\"404\" y=\"172\" font-size=\"10\" fill=\"#2f7d5b\">✓ 单颗粒分类准确率达到 92.4%，荧光定量面积 48.5%</text>\n</svg></div>\n<div class=\"figcap\"><b>图 2</b><span>传统目视估算未剔除掉块导致储层严重低估（左），AI 实例分割与上下文过滤精准还原储层岩性组分（右）。</span></div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>现代岩屑智能录井系统通过图像处理与机器学习实现从单颗粒物理特征提取到整井岩性剖面构建的全流程自动化：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 250\" width=\"100%\" role=\"img\" aria-label=\"双模态岩屑细粒度识别与综合柱状图构建架构图\">\n  <rect width=\"760\" height=\"250\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Stage 1 -->\n  <rect x=\"14\" y=\"24\" width=\"130\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"79\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">1. 标准暗箱双模态采集</text>\n  <rect x=\"24\" y=\"60\" width=\"110\" height=\"42\" rx=\"4\" fill=\"#e3ecf6\"/>\n  <text x=\"79\" y=\"78\" font-size=\"10\" font-weight=\"600\" fill=\"#3a6ea5\" text-anchor=\"middle\">D65 标准白光</text>\n  <text x=\"79\" y=\"93\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">内置 24 色卡动态校色</text>\n  <rect x=\"24\" y=\"112\" width=\"110\" height=\"42\" rx=\"4\" fill=\"#0f172a\"/>\n  <text x=\"79\" y=\"130\" font-size=\"10\" font-weight=\"600\" fill=\"#38bdf8\" text-anchor=\"middle\">365nm UV 荧光</text>\n  <text x=\"79\" y=\"145\" font-size=\"8.5\" fill=\"#94a3b8\" text-anchor=\"middle\">激发原油多环芳烃发光</text>\n  <text x=\"79\" y=\"185\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">36 颗湿颗粒/盘</text>\n\n  <line x1=\"144\" y1=\"125\" x2=\"162\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 2 -->\n  <rect x=\"166\" y=\"24\" width=\"144\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.3\"/>\n  <text x=\"238\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">2. 单颗粒实例分割</text>\n  <rect x=\"176\" y=\"58\" width=\"124\" height=\"66\" rx=\"4\" fill=\"#e3efec\"/>\n  <text x=\"238\" y=\"78\" font-size=\"10\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">轻量 Mask-RCNN</text>\n  <text x=\"238\" y=\"95\" font-size=\"9\" fill=\"#12615a\" text-anchor=\"middle\">分离金属网筛底座</text>\n  <text x=\"238\" y=\"110\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">消除水膜镜面强光斑</text>\n  <rect x=\"176\" y=\"132\" width=\"124\" height=\"66\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"238\" y=\"152\" font-size=\"10\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">颗粒几何物理参数</text>\n  <text x=\"238\" y=\"168\" font-size=\"9\" fill=\"#3a6ea5\" text-anchor=\"middle\">等效粒径 D (mm) 与 Φ</text>\n  <text x=\"238\" y=\"184\" font-size=\"9\" fill=\"#c27a2c\" text-anchor=\"middle\">圆度系数 (Roundness)</text>\n\n  <line x1=\"310\" y1=\"125\" x2=\"328\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 3 -->\n  <rect x=\"332\" y=\"24\" width=\"168\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#3a6ea5\" stroke-width=\"1.3\"/>\n  <text x=\"416\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#3a6ea5\" text-anchor=\"middle\">3. 细粒度岩性与荧光识别</text>\n  <rect x=\"344\" y=\"58\" width=\"144\" height=\"66\" rx=\"4\" fill=\"#e3ecf6\"/>\n  <text x=\"416\" y=\"78\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">纹理—粒径双分支融合</text>\n  <text x=\"416\" y=\"95\" font-size=\"9\" fill=\"#3a6ea5\" text-anchor=\"middle\">5类岩性分类准度 92.4%</text>\n  <text x=\"416\" y=\"112\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">细砂岩 / 泥质粉砂 / 泥岩</text>\n  <rect x=\"344\" y=\"132\" width=\"144\" height=\"64\" rx=\"4\" fill=\"#0f172a\"/>\n  <text x=\"416\" y=\"152\" font-size=\"10.5\" font-weight=\"600\" fill=\"#facc15\" text-anchor=\"middle\">UV 荧光发光面积积分</text>\n  <text x=\"416\" y=\"168\" font-size=\"9\" fill=\"#fde047\" text-anchor=\"middle\">定量定级：油浸/油斑/油迹</text>\n  <text x=\"416\" y=\"184\" font-size=\"8.5\" fill=\"#94a3b8\" text-anchor=\"middle\">色度坐标定位轻中质原油</text>\n\n  <line x1=\"500\" y1=\"125\" x2=\"518\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 4 -->\n  <rect x=\"522\" y=\"24\" width=\"224\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#2f7d5b\" stroke-width=\"1.3\"/>\n  <text x=\"634\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#2f7d5b\" text-anchor=\"middle\">4. 迟到归位与综合柱状图</text>\n  <rect x=\"534\" y=\"58\" width=\"200\" height=\"66\" rx=\"4\" fill=\"#f6e3df\"/>\n  <text x=\"634\" y=\"78\" font-size=\"10.5\" font-weight=\"700\" fill=\"#b4483c\" text-anchor=\"middle\">邻深上下文掉块过滤</text>\n  <text x=\"634\" y=\"96\" font-size=\"9\" fill=\"#b4483c\" text-anchor=\"middle\">大棱角泥岩掉块自动打叉剔除</text>\n  <text x=\"634\" y=\"112\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">岩性百分比 MAE 仅 1.8%</text>\n  <rect x=\"534\" y=\"132\" width=\"200\" height=\"64\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"634\" y=\"152\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">连续录井柱状图生成</text>\n  <text x=\"634\" y=\"170\" font-size=\"9\" fill=\"#2f7d5b\" text-anchor=\"middle\">迟到时间精准对齐深度 (2420-2490m)</text>\n  <text x=\"634\" y=\"186\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">直接赋能地质卡层与测井解释</text>\n</svg></div>\n<div class=\"figcap\"><b>图 3</b><span>双模态暗箱采图、单颗粒实例分割、细粒度纹理与荧光定量定级、迟到深度归位与综合柱状图构建的四级协同架构。</span></div>"},{"no":3,"en":"DATA","title":"数据采集与标准样盘","html":"<p>实施高精度岩屑自动识别，标准化制样与水力学参数采集是前提：</p>\n<div class=\"checklist\"><div class=\"cl-head\"><span>数据与工程准备清单 · 3 项（可点击勾选）</span><span class=\"cl-prog\"><span id=\"cl-txt\">0 / 3</span><span class=\"cl-bar\"><i id=\"cl-fill\"></i></span></span></div>\n  <div class=\"cl-item\" data-cl=\"0\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">标准显微暗箱白光与 365nm UV 双模态图像对</span><span class=\"cl-s\">每层样盘 36 颗独立摊铺岩屑颗粒，图像分辨率 ≥ 2048×1536，内置工业标准 24 色校色卡</span></span><span class=\"cl-n\">图像已消除金属网筛背景与水膜高反光</span></div>\n  <div class=\"cl-item\" data-cl=\"1\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">随钻水力参数与钻井工程时序数据</span><span class=\"cl-s\">泥浆泵排量 Q_in、井筒结构尺寸（钻杆/套管/裸眼外径）、立管压力及实时大钩深度</span></span><span class=\"cl-n\">用于计算动态岩屑迟到时间 Δt_lag 与深度归位</span></div>\n  <div class=\"cl-item\" data-cl=\"2\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">地层标准分层方案与薄片/衍射矿物鉴定基准</span><span class=\"cl-s\">邻井或本地区核心岩性鉴定标本（薄片鉴定长石/石英/黏土含量，XRD 矿物衍射数据）</span></span><span class=\"cl-n\">作为细粒度岩性分类与混淆矩阵校验基准</span></div>\n</div>\n<div class=\"figure\"><svg viewBox=\"0 0 760 215\" width=\"100%\" role=\"img\" aria-label=\"岩屑颗粒粒径分布直方图与岩性面积加权统计机制\">\n  <rect width=\"760\" height=\"215\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"24\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">颗粒粒径分布直方图 (mm / Φ) 与面积加权岩性组分计算机制</text>\n  <!-- Left: Grain size histogram -->\n  <rect x=\"16\" y=\"38\" width=\"354\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"28\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">A. 样盘 36 颗有效颗粒粒径直方图分布</text>\n  <!-- Bars -->\n  <rect x=\"40\" y=\"130\" width=\"35\" height=\"25\" fill=\"#7d8790\"/><text x=\"57\" y=\"125\" font-size=\"8.5\" fill=\"#15191c\" text-anchor=\"middle\">2</text>\n  <rect x=\"85\" y=\"115\" width=\"35\" height=\"40\" fill=\"#9ba89d\"/><text x=\"102\" y=\"110\" font-size=\"8.5\" fill=\"#15191c\" text-anchor=\"middle\">4</text>\n  <rect x=\"130\" y=\"95\" width=\"35\" height=\"60\" fill=\"#c4ba97\"/><text x=\"147\" y=\"90\" font-size=\"8.5\" fill=\"#15191c\" text-anchor=\"middle\">8</text>\n  <rect x=\"175\" y=\"65\" width=\"35\" height=\"90\" fill=\"#e0be6e\"/><text x=\"192\" y=\"60\" font-size=\"8.5\" fill=\"#15191c\" text-anchor=\"middle\">18</text>\n  <rect x=\"220\" y=\"135\" width=\"35\" height=\"20\" fill=\"#799ec2\"/><text x=\"237\" y=\"130\" font-size=\"8.5\" fill=\"#15191c\" text-anchor=\"middle\">0</text>\n  <text x=\"57\" y=\"168\" font-size=\"8\" fill=\"#737c83\" text-anchor=\"middle\">泥级</text>\n  <text x=\"102\" y=\"168\" font-size=\"8\" fill=\"#737c83\" text-anchor=\"middle\">细粉砂</text>\n  <text x=\"147\" y=\"168\" font-size=\"8\" fill=\"#737c83\" text-anchor=\"middle\">粗粉砂</text>\n  <text x=\"192\" y=\"168\" font-size=\"8\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">细砂岩</text>\n  <text x=\"28\" y=\"188\" font-size=\"9\" fill=\"#12615a\" font-weight=\"600\">细砂岩 (0.13-0.24mm) 占主导，粒径峰度与储层物性严格吻合。</text>\n\n  <!-- Right: Area Weighted Composition -->\n  <rect x=\"386\" y=\"38\" width=\"358\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"398\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">B. 单颗粒面积加权 vs 简单计数百分比</text>\n  <text x=\"398\" y=\"80\" font-size=\"9.5\" fill=\"#424a50\">简单计数忽略颗粒投影截面差异：1 颗大块掉块等于 4 颗小颗粒！</text>\n  <!-- Area-weighted bar -->\n  <rect x=\"398\" y=\"95\" width=\"330\" height=\"24\" rx=\"4\" fill=\"#e7e3da\"/>\n  <rect x=\"398\" y=\"95\" width=\"238\" height=\"24\" rx=\"3\" fill=\"#e0be6e\"/><text x=\"517\" y=\"111\" font-size=\"10\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">细砂岩 72.0% (储层真值)</text>\n  <rect x=\"636\" y=\"95\" width=\"52\" height=\"24\" fill=\"#c4ba97\"/><text x=\"662\" y=\"111\" font-size=\"8.5\" fill=\"#15191c\" text-anchor=\"middle\">16%</text>\n  <rect x=\"688\" y=\"95\" width=\"24\" height=\"24\" fill=\"#9ba89d\"/>\n  <rect x=\"712\" y=\"95\" width=\"16\" height=\"24\" rx=\"3\" fill=\"#7d8790\"/>\n  <text x=\"398\" y=\"145\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"700\">✓ 结合等效投影椭球体积加权积分，彻底消除颗粒大小不均偏差</text>\n  <text x=\"398\" y=\"165\" font-size=\"9.5\" fill=\"#2f7d5b\">✓ 组分绝对误差 MAE 控制在 1.8% 优级标准</text>\n  <text x=\"398\" y=\"185\" font-size=\"9\" fill=\"#737c83\">行业标准：综合录井剖面砂岩组分允许误差为 ±5%，本系统远优于标准。</text>\n</svg></div>\n<div class=\"figcap\"><b>图 4</b><span>岩屑颗粒粒径分布直方图（左）与投影截面面积加权岩性组分计算机制（右）。</span></div>"},{"no":4,"en":"DIFFICULTY","title":"工程瓶颈与对策","html":"<p>岩屑智能录井落地必须攻克掉块干扰、荧光定级与迟到归位三大关键：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 225\" width=\"100%\" role=\"img\" aria-label=\"荧光发光阈值权衡与录井五维落地难度\">\n  <rect width=\"760\" height=\"225\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: UV Threshold Tradeoff -->\n  <rect x=\"14\" y=\"14\" width=\"368\" height=\"197\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"26\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. 紫外荧光有效分割阈值与原油定级灵敏度权衡</text>\n  <line x1=\"56\" y1=\"176\" x2=\"356\" y2=\"176\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <line x1=\"56\" y1=\"48\" x2=\"56\" y2=\"176\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <text x=\"206\" y=\"196\" font-size=\"10\" fill=\"#424a50\" text-anchor=\"middle\">紫外荧光分割亮度阈值 → 越高越严格</text>\n  <path d=\"M65,65 Q180,110 340,165\" fill=\"none\" stroke=\"#b4483c\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"145\" font-size=\"9\" fill=\"#b4483c\">矿物自发光伪荧光误报</text>\n  <path d=\"M65,165 Q180,110 340,65\" fill=\"none\" stroke=\"#facc15\" stroke-width=\"2.2\"/>\n  <text x=\"250\" y=\"80\" font-size=\"9\" fill=\"#b45309\" font-weight=\"700\">有效原油荧光漏检率</text>\n  <line x1=\"210\" y1=\"48\" x2=\"210\" y2=\"176\" stroke=\"#12615a\" stroke-dasharray=\"3,2\"/>\n  <circle cx=\"210\" cy=\"110\" r=\"5\" fill=\"#12615a\"/>\n  <text x=\"210\" y=\"42\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">推荐工业平衡阈值 0.32</text>\n\n  <!-- Right: 5-D Difficulty -->\n  <rect x=\"394\" y=\"14\" width=\"352\" height=\"197\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"408\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. 岩屑录井智能识别工程落地五维技术难度剖析</text>\n  <g font-size=\"10\" fill=\"#424a50\">\n    <text x=\"408\" y=\"60\">上部地层垮塌掉块严重混淆</text><rect x=\"546\" y=\"51\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"51\" width=\"144\" height=\"10\" rx=\"3\" fill=\"#b4483c\"/><text x=\"708\" y=\"60\" font-family=\"ui-monospace,Consolas,monospace\">9.3</text>\n    <text x=\"408\" y=\"90\">泥浆添加剂强假荧光干扰污染</text><rect x=\"546\" y=\"81\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"81\" width=\"136\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"90\" font-family=\"ui-monospace,Consolas,monospace\">8.7</text>\n    <text x=\"408\" y=\"120\">过渡岩性粒径微结构连续渐变</text><rect x=\"546\" y=\"111\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"111\" width=\"124\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"120\" font-family=\"ui-monospace,Consolas,monospace\">8.0</text>\n    <text x=\"408\" y=\"150\">迟到时间动态漂移与深度错位</text><rect x=\"546\" y=\"141\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"141\" width=\"115\" height=\"10\" rx=\"3\" fill=\"#3a6ea5\"/><text x=\"708\" y=\"150\" font-family=\"ui-monospace,Consolas,monospace\">7.4</text>\n    <text x=\"408\" y=\"180\">湿样水膜反光与暗箱色卡校准</text><rect x=\"546\" y=\"171\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"171\" width=\"102\" height=\"10\" rx=\"3\" fill=\"#12615a\"/><text x=\"708\" y=\"180\" font-family=\"ui-monospace,Consolas,monospace\">6.6</text>\n  </g>\n</svg></div>\n<div class=\"figcap\"><b>图 5</b><span>紫外荧光分割亮度阈值在假荧光与漏检之间的权衡曲线（左）及岩屑识别工程落地五维技术难度剖析（右）。</span></div>\n<p>关联方法与技术方向：</p>\n<div class=\"refs\">\n  <a class=\"ref\" href=\"#/method/cv\">多模态显微图像实例分割<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">双分支细粒度纹理识别网络<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">颗粒等效粒径与圆度几何分析<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">365nm 紫外荧光定量定级<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">迟到时间深度归位与综合柱状图<span class=\"ar\">↗</span></a>\n</div>"}]},"workflow":{"label":"案例流程","title":"双模态岩屑随钻智能录井流水线","lead":["涵盖暗箱采图、单颗粒实例分割、粒径与荧光定量计算到迟到归位综合柱状图构建。"],"stats":[["每盘颗粒","36 颗"],["剖面深度","2420~2490 m"],["组分误差","MAE 1.8%"]],"steps":[{"name":"标准暗箱双模态采图与色卡校准","role":"数据","do":"振动筛清洗捞砂后平铺入盘，在 D65 白光与 365nm UV 光源下采集标准显微图像，完成色度校准。","effect":"消除现场不同天气与照明色温波动，获得稳定岩屑表面真彩色与真实荧光辉度。","trap":"水膜未擦干容易在强白光下形成高光镜面反射亮点，影响模型纹理提取。"},{"name":"单颗岩屑前景分割与泥浆伪影剔除","role":"算法","do":"使用轻量实例分割网络提取 36 颗岩屑独立轮廓多边形，剥离金属网筛与泥浆包裹斑块。","effect":"实现 100% 颗粒独立化与单颗粒特征解耦，计算每颗岩屑等效粒径与圆度。","trap":"细粉砂颗粒易黏结团聚，必须施加形态学分水岭算法精细分割接触边缘。"},{"name":"细粒度岩性纹理与粒径分布识别","role":"算法","do":"双分支融合卷积网络，综合颜色纹理微结构与粒径分布直方图，输出 5 类过渡岩性概率。","effect":"颗粒分类准确率达到 92.4%，有效区分细砂岩、泥质粉砂与粉砂质泥岩。","trap":"泥浆浸染严重时会把浅色砂岩染成灰色，需要结合粒径特征进行加权纠偏。"},{"name":"紫外荧光有效发光面积与油质分级","role":"特征","do":"在紫外视场对各有效颗粒发光面积做自适应阈值分割积分，分析色度坐标判定含油级别。","effect":"定量定级为油浸级/油斑级/油迹级/无荧光，并识别凝析油与中重质原油类型。","trap":"柴油基泥浆添加剂具有天然假荧光，需提取特定发射光谱带进行滤除。"},{"name":"迟到深度归位与综合柱状图生成","role":"交付","do":"根据环空排量与井筒容积推算迟到时间归位真实井深，上下文过滤掉块，输出连续录井剖面。","effect":"组分百分比 MAE 仅为 1.8%，真实还原 2452m 主力储层 72% 细砂岩组分。","trap":"钻速突增或泥浆泵排量变化时若未动态更新迟到时间，会导致岩性柱状图发生深度错位。"}],"metrics":{"title":"流程分镜与验收指标","html":"<p>以下五步分镜展示从原始多源观测输入到最终工程可交付成果的完整演进过程与定量验收标准：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 220\" width=\"100%\" role=\"img\" aria-label=\"流程分镜与验收指标五步流程分镜\">\n  <rect width=\"760\" height=\"220\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <g transform=\"translate(12,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#12615a\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">01</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">暗箱双模态采图</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#ebe6da\"/>\n    <circle cx=\"50\" cy=\"75\" r=\"14\" fill=\"#e0be6e\" stroke=\"#424a50\"/>\n    <circle cx=\"85\" cy=\"85\" r=\"12\" fill=\"#c4ba97\" stroke=\"#424a50\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#15191c\" text-anchor=\"middle\">多颗粒样盘采图</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">D65白光 + 365nm UV</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">标准24色卡动态校准</text>\n    </g>\n<g transform=\"translate(161,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#3a6ea5\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">02</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">单颗粒前景分割</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#e3efec\"/>\n    <circle cx=\"50\" cy=\"80\" r=\"16\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.8\"/>\n    <circle cx=\"88\" cy=\"80\" r=\"14\" fill=\"none\" stroke=\"#3a6ea5\" stroke-width=\"1.8\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">多边形轮廓提取</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">Mask-RCNN 实例剥离</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">提取等效粒径与圆度</text>\n    </g>\n<g transform=\"translate(310,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#6b5aa6\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">03</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">细粒度岩性识别</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#e3ecf6\"/>\n    <rect x=\"25\" y=\"55\" width=\"40\" height=\"40\" rx=\"3\" fill=\"#e0be6e\"/>\n    <rect x=\"73\" y=\"55\" width=\"40\" height=\"40\" rx=\"3\" fill=\"#c4ba97\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#3a6ea5\" text-anchor=\"middle\">细砂岩/泥粉砂区分</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">纹理—粒径双分支网络</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">单颗粒分类准度 92.4%</text>\n    </g>\n<g transform=\"translate(459,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#c27a2c\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">04</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">UV 荧光定量定级</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#0b101b\"/>\n    <circle cx=\"69\" cy=\"80\" r=\"18\" fill=\"rgba(250,204,21,0.7)\" stroke=\"#facc15\" stroke-width=\"1.5\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#fde047\" text-anchor=\"middle\">365nm 发光积分</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">有效发光面积 48.5%</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">定级油浸级 (轻中质油)</text>\n    </g>\n<g transform=\"translate(608,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#2f7d5b\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">05</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">迟到归位与柱状图</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\"/>\n    <rect x=\"30\" y=\"52\" width=\"20\" height=\"60\" fill=\"#e0be6e\"/>\n    <rect x=\"52\" y=\"52\" width=\"16\" height=\"60\" fill=\"#c4ba97\"/>\n    <rect x=\"70\" y=\"52\" width=\"26\" height=\"60\" fill=\"#7d8790\"/>\n    <text x=\"69\" y=\"122\" font-size=\"8.5\" fill=\"#2f7d5b\" text-anchor=\"middle\" font-weight=\"700\">综合剖面生成</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">邻深掉块过滤 (MAE 1.8%)</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">输出 2420-2490m 柱状图</text>\n    </g>\n</svg></div>\n<div class=\"figcap\"><b>图 6</b><span>五步岩屑智能识别流程分镜：从双模态暗箱采图（01）到颗粒分割、细粒度岩性、UV荧光定级与综合柱状图构建（05）。</span></div>\n<div class=\"figure\"><svg viewBox=\"0 0 760 185\" width=\"100%\" role=\"img\" aria-label=\"核心验收指标示意图\">\n  <rect width=\"760\" height=\"185\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <g transform=\"translate(14,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#12615a\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">1. 单颗粒岩性分类准确率</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">Accuracy = N_correct / N_valid</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"600\">参考基准线：准确率 ≥ 90%</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 细粒度双分支融合纹理与粒径特征</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 有效解决泥浆包裹带来的色偏混淆</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：单颗粒准确率 = 92.4%</text>\n    </g>\n<g transform=\"translate(263,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#3a6ea5\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#3a6ea5\">2. 岩性组分百分比误差 MAE</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">MAE = (1/K) · Σ |P_pred - P_true|</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#3a6ea5\" font-weight=\"600\">参考基准线：MAE ≤ 3.0%</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 未开启掉块过滤前原始 MAE 为 8.6%</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 上下文过滤大块尖锐垮塌泥岩</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：组分百分比 MAE = 1.8%</text>\n    </g>\n<g transform=\"translate(512,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#c27a2c\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#c27a2c\">3. 紫外荧光含油级别定级吻合率</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">Grade Consistency ≥ 95%</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#c27a2c\" font-weight=\"600\">参考基准线：吻合率 ≥ 95%</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 2452m 储层紫外有效发光占比 48.5%</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 准确评定为油浸级，指导储层精准卡层</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：含油定级吻合率 97.2%</text>\n    </g>\n</svg></div>\n<div class=\"figcap\"><b>图 7</b><span>工程交付三大定量验收标准：单颗粒分类准确率、岩性组分绝对误差 MAE 与紫外荧光定级吻合率。</span></div>"},"fails":[{"name":"上部掉块混淆真储层","why":"未开启上下文掉块剔除时，上覆大块垮塌泥岩进入样盘，使主力砂岩储层含砂率严重偏低。"},{"name":"水膜镜面强光耀斑","why":"未沥干颗粒表面水膜在高倍光源下呈现纯白高光，被误判为生屑灰岩或方解石脉。"},{"name":"荧光钻井液添加剂干扰","why":"混入抗磨润滑剂的高亮蓝绿荧光伪影，导致干层或水层被误定为轻质油显示。"}]},"demo":{"mode":"auto","html":"demo/index.html","label":"可运行示范","intro":"","height":980}}},"files":[{"name":"demo/index.html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>白光与紫外荧光双模态岩屑细粒度识别与综合柱状图构建</title>\n  <link rel=\"stylesheet\" href=\"demo.css\" />\n</head>\n<body>\n<div class=\"app\">\n  <!-- 顶栏：仅标题与实时状态胶囊，无副标题 -->\n  <header class=\"topbar\">\n    <h1>白光与紫外荧光双模态岩屑细粒度识别与综合柱状图构建</h1>\n    <div class=\"sp\"></div>\n    <span class=\"pill acc\" id=\"pillDepth\"><i></i><span>当前迟到归位深度：2452.0 m</span></span>\n    <span class=\"pill ok\" id=\"pillOil\"><i></i><span>荧光定级：油浸级（主力油层）</span></span>\n    <span class=\"pill ok\" id=\"pillStatus\"><i></i><span>掉块剔除已开启 · MAE 1.8%</span></span>\n  </header>\n\n  <!-- 5 步流程步进条 -->\n  <nav class=\"stepper\" id=\"stepper\" aria-label=\"案例流程步进\">\n    <button type=\"button\" data-step=\"0\">\n      <span class=\"n\">STEP 01</span>\n      <span class=\"t\">标准暗箱双模态采图与色卡校准</span>\n    </button>\n    <button type=\"button\" data-step=\"1\">\n      <span class=\"n\">STEP 02</span>\n      <span class=\"t\">单颗岩屑前景分割与泥浆伪影剔除</span>\n    </button>\n    <button type=\"button\" data-step=\"2\">\n      <span class=\"n\">STEP 03</span>\n      <span class=\"t\">细粒度岩性纹理与粒径分布识别</span>\n    </button>\n    <button type=\"button\" data-step=\"3\">\n      <span class=\"n\">STEP 04</span>\n      <span class=\"t\">紫外荧光有效发光面积与油质分级</span>\n    </button>\n    <button type=\"button\" data-step=\"4\" class=\"on\">\n      <span class=\"n\">STEP 05</span>\n      <span class=\"t\">迟到深度归位与岩性百分比柱状图生成</span>\n    </button>\n  </nav>\n\n  <!-- 主工作台 -->\n  <div class=\"bench\">\n    <!-- 左侧参数控制栏 -->\n    <aside class=\"rail\">\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>光源模态与标注视图</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">点击切换</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"seg\" id=\"segMode\">\n            <button type=\"button\" data-mode=\"white\">白光显微</button>\n            <button type=\"button\" data-mode=\"uv\">紫外荧光 UV</button>\n            <button type=\"button\" data-mode=\"ai\" class=\"on\">AI实例分割标注</button>\n          </div>\n          <div style=\"margin-top:9px\">\n            <label class=\"check\">\n              <input type=\"checkbox\" id=\"chkSplit\" />\n              <span>白光 / 365nm 荧光双屏同框对比</span>\n            </label>\n            <label class=\"check\">\n              <input type=\"checkbox\" id=\"chkRuler\" checked />\n              <span>显示颗粒等效粒径标尺与编号</span>\n            </label>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>储盖层剖面深度采样点</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">2420–2490m · 8层</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"depth-list\" id=\"depthList\"></div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>井筒干扰与算法超参数</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">实时重算</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>上部掉块混样比例</span>\n              <output id=\"outCaving\">12%</output>\n            </div>\n            <input type=\"range\" id=\"rngCaving\" min=\"0\" max=\"30\" step=\"2\" value=\"12\" />\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>泥浆包裹污染度</span>\n              <output id=\"outMud\">0.15</output>\n            </div>\n            <input type=\"range\" id=\"rngMud\" min=\"0\" max=\"0.8\" step=\"0.05\" value=\"0.15\" />\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>荧光发光分割阈值</span>\n              <output id=\"outUvThr\">0.32</output>\n            </div>\n            <input type=\"range\" id=\"rngUvThr\" min=\"0.15\" max=\"0.65\" step=\"0.02\" value=\"0.32\" />\n          </div>\n\n          <div class=\"divider\"></div>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chkCavingFilter\" checked />\n            <span>启用邻深上下文掉块剔除算法</span>\n          </label>\n\n          <div class=\"btn-row\">\n            <button type=\"button\" class=\"btn primary\" id=\"btnScan\">逐层巡检播放</button>\n            <button type=\"button\" class=\"btn\" id=\"btnReset\">重置参数</button>\n          </div>\n        </div>\n      </div>\n    </aside>\n\n    <!-- 右侧主舞台 -->\n    <main class=\"stage\">\n      <div class=\"view\">\n        <div class=\"view-h\">\n          <span id=\"stageTitle\">高倍岩屑样盘双模态显微镜（36 颗湿样颗粒） + 2420–2490m 随钻录井岩性剖面联动图</span>\n          <span class=\"sp\"></span>\n          <span class=\"muted small\" id=\"lagBadge\">迟到时间 Δt_lag = 34.5 min · 钻时 ROP = 1.8 min/m</span>\n        </div>\n\n        <div class=\"dual-workbench\">\n          <!-- 左：高倍岩屑样盘显微镜 Canvas -->\n          <div class=\"tray-pane\">\n            <div class=\"tray-canvas-wrap\" id=\"trayWrap\">\n              <canvas id=\"trayCanvas\" width=\"520\" height=\"440\"></canvas>\n              <div class=\"tip\" id=\"trayTip\"></div>\n            </div>\n          </div>\n\n          <!-- 右：2420m-2490m 随钻录井岩性百分比与荧光级别综合柱状图 SVG -->\n          <div class=\"strip-pane\">\n            <div class=\"strip-svg-wrap\">\n              <svg id=\"stripSvg\" viewBox=\"0 0 430 430\" width=\"100%\" role=\"img\" aria-label=\"2420m至2490m随钻录井岩性百分比与含油级别综合柱状图\"></svg>\n            </div>\n          </div>\n        </div>\n\n        <!-- 单颗岩屑显微放大镜检视栏（点击或悬停样盘中任一颗粒实时更新） -->\n        <div class=\"chip-inspector\">\n          <div class=\"chip-zoom-box\">\n            <canvas id=\"zoomCanvas\" width=\"128\" height=\"104\"></canvas>\n          </div>\n          <div class=\"chip-meta\">\n            <div class=\"chip-meta-top\" id=\"chipHeader\">\n              <b>颗粒 #08 · 细砂岩（Fine Sandstone）</b>\n              <span class=\"chip-badge normal\">原位地层颗粒</span>\n              <span class=\"chip-badge uv-hi\">UV 亮黄发光 78%</span>\n            </div>\n            <div class=\"chip-probs\" id=\"chipSpecs\">\n              等效粒径 D = 0.19 mm (Φ = 2.40) · 圆度 0.72 · RGB(204,185,148) / HSV(40°,27%,80%)\n            </div>\n            <div class=\"chip-probs\" id=\"chipProbs\">\n              预测概率：细砂岩 86.4% | 泥质粉砂 8.2% | 粉砂质泥 3.1% | 泥岩 1.4% | 灰岩 0.9%\n            </div>\n          </div>\n          <div style=\"text-align:right\">\n            <div class=\"small muted\">点击样盘颗粒锁定 · 点击右图深度切层</div>\n            <div class=\"mono\" style=\"font-size:11.5px;color:var(--accent);font-weight:600\" id=\"chipCountInfo\">有效颗粒 32 / 掉块剔除 4</div>\n          </div>\n        </div>\n\n        <div class=\"view-f\">\n          <div class=\"legend\">\n            <span><i style=\"background:#7d8790\"></i>泥岩</span>\n            <span><i style=\"background:#9ba89d\"></i>粉砂质泥岩</span>\n            <span><i style=\"background:#c4ba97\"></i>泥质粉砂岩</span>\n            <span><i style=\"background:#e0be6e\"></i>细砂岩（储层）</span>\n            <span><i style=\"background:#799ec2\"></i>生物碎屑灰岩</span>\n            <span><i style=\"background:#38e54d;border-radius:50%\"></i>365nm 紫外荧光含油区</span>\n            <span><i style=\"background:#b4483c\"></i>上部井壁掉块（AI剔除）</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- 4 个实时 KPI -->\n      <section class=\"kpis\">\n        <div class=\"kpi ok\" id=\"kpiAccBox\">\n          <div class=\"k\">单颗粒分类准确率</div>\n          <div class=\"v\" id=\"kpiAcc\">92.4<small>%</small></div>\n          <div class=\"d\" id=\"kpiAccDesc\">白光纹理+粒径双分支融合</div>\n        </div>\n        <div class=\"kpi ok\" id=\"kpiMaeBox\">\n          <div class=\"k\">岩性组分百分比误差 MAE</div>\n          <div class=\"v\" id=\"kpiMae\">1.8<small>%</small></div>\n          <div class=\"d\" id=\"kpiMaeDesc\">对比未剔除掉块误差 8.6%</div>\n        </div>\n        <div class=\"kpi acc\" id=\"kpiUvBox\">\n          <div class=\"k\">荧光含油面积占比</div>\n          <div class=\"v\" id=\"kpiUvArea\">48.5<small>%</small></div>\n          <div class=\"d\" id=\"kpiUvDesc\">365nm 有效发光像素积分</div>\n        </div>\n        <div class=\"kpi ok\" id=\"kpiGradeBox\">\n          <div class=\"k\">综合判定含油级别</div>\n          <div class=\"v\" id=\"kpiGrade\">油浸级<small>Oil-Immersed</small></div>\n          <div class=\"d\" id=\"kpiGradeDesc\">亮黄金黄荧光 · 轻—中质原油</div>\n        </div>\n      </section>\n\n      <!-- 2 张辅助分析图 -->\n      <section class=\"grid2\">\n        <div class=\"card\">\n          <div class=\"card-h\">\n            <span>当前样盘粒径分布直方图（Φ / mm）与岩性组分占比</span>\n            <span class=\"sp\"></span>\n            <span class=\"hint\" id=\"grainHint\">深度 2452.0m 统计</span>\n          </div>\n          <div class=\"card-b\" style=\"padding:10px 12px\">\n            <svg id=\"grainSvg\" viewBox=\"0 0 420 225\" width=\"100%\" role=\"img\" aria-label=\"当前样盘粒径分布直方图与岩性面积占比图\"></svg>\n          </div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-h\">\n            <span>细粒度岩性 5×5 混淆矩阵与紫外荧光色度油质图版</span>\n            <span class=\"sp\"></span>\n            <span class=\"hint\" id=\"matrixHint\">Top-1 准确率与色度坐标</span>\n          </div>\n          <div class=\"card-b\" style=\"padding:10px 12px\">\n            <svg id=\"matrixUvSvg\" viewBox=\"0 0 420 225\" width=\"100%\" role=\"img\" aria-label=\"细粒度岩性混淆矩阵与紫外荧光色度原油性质判别图\"></svg>\n          </div>\n        </div>\n      </section>\n\n      <!-- 动态专业解读 -->\n      <div class=\"insight\" id=\"insightBox\">\n        <div class=\"tag\" id=\"insightTag\">机理解读</div>\n        <div id=\"insightText\"></div>\n      </div>\n    </main>\n  </div>\n</div>\n<script src=\"demo.js\"></script>\n</body>\n</html>\n","enc":"text","size":10516},{"name":"demo/demo.css","data":"/* =========================================================\n   Demo Kit · 案例示范统一样式（每个案例的 demo.css 顶部整段复制本文件）\n   ---------------------------------------------------------\n   运行在沙箱 iframe 里，与主站完全隔离；只用系统字体，离线可用。\n   结构：.app > .topbar + .stepper? + .bench(.rail + .stage) + .kpis + .grid2 + .insight\n   ========================================================= */\n:root{\n  --paper:#f7f5f0; --paper-2:#f0ede5; --surface:#ffffff;\n  --ink:#15191c; --ink-2:#424a50; --ink-3:#737c83; --ink-4:#a3aab0;\n  --line:#e7e3da; --line-2:#d9d4c8;\n  --accent:#12615a; --accent-2:#1d7f75; --accent-l:#e3efec;\n  --amber:#c27a2c; --amber-l:#f7ecdd;\n  --red:#b4483c;  --red-l:#f6e3df;\n  --green:#2f7d5b; --green-l:#e2f0e8;\n  --blue:#3a6ea5; --blue-l:#e3ecf6;\n  --violet:#6b5aa6; --violet-l:#ebe7f5;\n  --sans:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Microsoft YaHei\",\"Noto Sans SC\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"JetBrains Mono\",\"Cascadia Code\",\"SF Mono\",Consolas,ui-monospace,monospace;\n  --r:12px; --r-s:8px;\n  --sh:0 1px 2px rgba(21,25,28,.04),0 6px 24px -12px rgba(21,25,28,.12);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--paper);color:var(--ink)}\nbody{font-family:var(--sans);font-size:13px;line-height:1.7;-webkit-font-smoothing:antialiased;padding:20px 22px 26px}\nb,strong{font-weight:650}\n.mono{font-family:var(--mono)}\n.app{max-width:1160px;margin:0 auto}\n\n/* ---------- 顶栏：只有标题 + 右侧状态胶囊，不放副标题 ---------- */\n.topbar{display:flex;align-items:center;gap:14px;padding-bottom:14px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.topbar h1{font-size:19px;line-height:1.3;margin:0;letter-spacing:-.01em;font-weight:700}\n.topbar .sp{flex:1}\n.pill{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:999px;font-size:11.5px;\n  border:1px solid var(--line-2);background:var(--surface);color:var(--ink-2);white-space:nowrap}\n.pill i{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}\n.pill.ok{color:var(--green);border-color:rgba(47,125,91,.28);background:var(--green-l)}\n.pill.warn{color:var(--amber);border-color:rgba(194,122,44,.3);background:var(--amber-l)}\n.pill.bad{color:var(--red);border-color:rgba(180,72,60,.28);background:var(--red-l)}\n.pill.acc{color:var(--accent);border-color:rgba(18,97,90,.25);background:var(--accent-l)}\n\n/* ---------- 流程步进条：与「案例流程」tab 的步骤一一对应 ---------- */\n.stepper{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:0;margin:0 0 16px;\n  background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.stepper button{all:unset;cursor:pointer;position:relative;padding:11px 14px 11px 16px;border-right:1px solid var(--line);\n  display:flex;flex-direction:column;gap:2px;transition:background .18s}\n.stepper button:last-child{border-right:0}\n.stepper button .n{font-family:var(--mono);font-size:10.5px;color:var(--ink-4);letter-spacing:.06em}\n.stepper button .t{font-size:12.5px;font-weight:600;color:var(--ink-2)}\n.stepper button:hover{background:var(--paper)}\n.stepper button.on{background:var(--accent-l)}\n.stepper button.on .n{color:var(--accent)}\n.stepper button.on .t{color:var(--accent)}\n.stepper button.on::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--accent)}\n.stepper button.done .n::after{content:\" ✓\";color:var(--green)}\n\n/* ---------- 工作台：左控制栏 + 右主画布 ---------- */\n.bench{display:grid;grid-template-columns:270px 1fr;gap:16px;align-items:start}\n.rail{display:flex;flex-direction:column;gap:12px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}\n.card-h{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);\n  font-size:12px;font-weight:650;color:var(--ink-2)}\n.card-h .sp{flex:1}\n.card-h .hint{font-weight:400;color:var(--ink-4);font-size:11px}\n.card-b{padding:12px 14px}\n.stage{min-width:0;display:flex;flex-direction:column;gap:16px}\n.view{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}\n.view canvas,.view svg{display:block;width:100%;height:auto}\n.view-h{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12px;font-weight:650;color:var(--ink-2)}\n.view-h .sp{flex:1}\n.view-f{display:flex;flex-wrap:wrap;gap:6px 16px;padding:9px 14px;border-top:1px solid var(--line);font-size:11.5px;color:var(--ink-3)}\n\n/* ---------- 控件 ---------- */\n.ctl{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}\n.ctl:last-child{margin-bottom:0}\n.ctl-l{display:flex;align-items:baseline;justify-content:space-between;font-size:12px;color:var(--ink-2)}\n.ctl-l output,.ctl-l .v{font-family:var(--mono);font-size:12px;color:var(--accent);font-weight:600}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:20px;background:transparent;margin:0}\ninput[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:4px;background:linear-gradient(90deg,var(--accent) var(--p,50%),var(--line) var(--p,50%))}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;margin-top:-6px;\n  background:#fff;border:2px solid var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.15)}\ninput[type=range]::-moz-range-track{height:4px;border-radius:4px;background:var(--line)}\ninput[type=range]::-moz-range-progress{height:4px;border-radius:4px;background:var(--accent)}\ninput[type=range]::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:#fff;border:2px solid var(--accent)}\n.seg{display:flex;background:var(--paper-2);border-radius:9px;padding:3px;gap:3px}\n.seg button{all:unset;flex:1;text-align:center;cursor:pointer;font-size:12px;padding:5px 6px;border-radius:7px;color:var(--ink-3);transition:all .15s}\n.seg button:hover{color:var(--ink)}\n.seg button.on{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.btn{all:unset;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 14px;\n  border-radius:9px;font-size:12.5px;font-weight:600;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);transition:all .15s}\n.btn:hover{border-color:var(--ink-3)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn.primary:hover{background:var(--accent-2)}\n.btn.block{display:flex;width:100%;box-sizing:border-box}\n.btn:disabled,.btn.disabled{opacity:.45;pointer-events:none}\n.check{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-2);cursor:pointer;user-select:none;margin:4px 0}\n.check input{accent-color:var(--accent);width:14px;height:14px;margin:0}\n\n/* ---------- 指标条 ---------- */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0;background:var(--surface);\n  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.kpi{padding:12px 16px;border-right:1px solid var(--line)}\n.kpi:last-child{border-right:0}\n.kpi .k{font-size:11px;color:var(--ink-3);letter-spacing:.02em}\n.kpi .v{font-family:var(--mono);font-size:22px;font-weight:600;line-height:1.25;margin-top:3px;letter-spacing:-.02em}\n.kpi .v small{font-size:12px;color:var(--ink-3);font-weight:500;margin-left:3px}\n.kpi .d{font-size:11px;color:var(--ink-4);margin-top:2px}\n.kpi.ok .v{color:var(--green)} .kpi.bad .v{color:var(--red)} .kpi.warn .v{color:var(--amber)} .kpi.acc .v{color:var(--accent)}\n\n/* ---------- 栅格 ---------- */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n\n/* ---------- 图例 ---------- */\n.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11.5px;color:var(--ink-3)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.legend i{width:10px;height:10px;border-radius:3px;display:inline-block}\n.legend i.line{height:2px;width:14px;border-radius:0}\n.legend i.dash{height:0;width:14px;border-top:2px dashed currentColor;border-radius:0}\n\n/* ---------- 解读：随参数变化的动态说明 ---------- */\n.insight{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start;padding:13px 16px;border-radius:var(--r);\n  background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--accent);box-shadow:var(--sh);font-size:12.5px;color:var(--ink-2);line-height:1.8}\n.insight .tag{font-size:11px;font-weight:700;color:var(--accent);letter-spacing:.08em;padding-top:2px;white-space:nowrap}\n.insight.warn{border-left-color:var(--amber)} .insight.warn .tag{color:var(--amber)}\n.insight.bad{border-left-color:var(--red)} .insight.bad .tag{color:var(--red)}\n.insight b{color:var(--ink)}\n\n/* ---------- 表格 ---------- */\ntable.t{width:100%;border-collapse:collapse;font-size:12px}\ntable.t th{text-align:left;font-weight:600;color:var(--ink-3);font-size:11px;padding:7px 10px;border-bottom:1px solid var(--line);background:var(--paper)}\ntable.t td{padding:7px 10px;border-bottom:1px solid var(--line);color:var(--ink-2)}\ntable.t td.num{font-family:var(--mono);text-align:right}\ntable.t tr:last-child td{border-bottom:0}\n\n/* ---------- 浮动提示 ---------- */\n.tip{position:absolute;pointer-events:none;z-index:5;background:rgba(21,25,28,.92);color:#fff;font-size:11.5px;line-height:1.6;\n  padding:7px 10px;border-radius:7px;white-space:nowrap;transform:translate(-50%,calc(-100% - 10px));opacity:0;transition:opacity .12s}\n.tip.on{opacity:1}\n.tip b{color:#fff}\n\n/* ---------- 小工具 ---------- */\n.muted{color:var(--ink-3)} .small{font-size:11.5px}\n.row{display:flex;align-items:center;gap:8px}\n.divider{height:1px;background:var(--line);margin:12px 0}\n.bar{height:6px;border-radius:6px;background:var(--paper-2);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:6px;background:var(--accent);transition:width .3s}\n.fade-in{animation:fi .35s ease both}\n@keyframes fi{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}\n\n@media (max-width:860px){\n  .bench{grid-template-columns:1fr}\n  .grid2,.grid3{grid-template-columns:1fr}\n  .stepper{grid-auto-flow:row}\n  .stepper button{border-right:0;border-bottom:1px solid var(--line)}\n}\n/* ===================== Demo Kit 结束 ===================== */\n\n/* =========================================================\n   本案例专属样式：双模态岩屑样盘显微镜 + 随钻录井综合柱状图工作台\n   ========================================================= */\n.bench{grid-template-columns:280px 1fr}\n\n/* 深度样点列表 */\n.depth-list{display:flex;flex-direction:column;gap:4px;max-height:224px;overflow-y:auto;padding-right:2px}\n.depth-btn{all:unset;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:6px;\n  padding:5px 8px;border-radius:7px;border:1px solid var(--line);background:var(--paper);font-size:11.5px;color:var(--ink-2);transition:all .14s}\n.depth-btn:hover{border-color:var(--accent);background:#fff}\n.depth-btn.on{border-color:var(--accent);background:var(--accent-l);color:var(--ink);font-weight:600}\n.depth-btn .dp-m{font-family:var(--mono);font-size:11px;font-weight:650;color:var(--accent);min-width:44px}\n.depth-btn .dp-name{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.depth-btn .dp-tag{font-size:10px;padding:1px 5px;border-radius:4px;font-weight:600;white-space:nowrap}\n.dp-tag.oil-imm{background:#f7ecdd;color:#9a5b13;border:1px solid rgba(194,122,44,.35)}\n.dp-tag.oil-spot{background:#e2f0e8;color:#2f7d5b;border:1px solid rgba(47,125,91,.3)}\n.dp-tag.oil-trace{background:#e3ecf6;color:#3a6ea5;border:1px solid rgba(58,110,165,.28)}\n.dp-tag.oil-none{background:#f0ede5;color:#737c83;border:1px solid var(--line-2)}\n\n/* 主舞台内部：左显微镜样盘 + 右录井综合柱状图 */\n.dual-workbench{display:grid;grid-template-columns:1.08fr 0.92fr;gap:0;border-bottom:1px solid var(--line)}\n.tray-pane{position:relative;border-right:1px solid var(--line);background:#1b1f22;display:flex;flex-direction:column}\n.tray-canvas-wrap{position:relative;width:100%;aspect-ratio:480/410;overflow:hidden;cursor:crosshair}\n.tray-canvas-wrap canvas{width:100%;height:100%;display:block}\n.strip-pane{background:var(--surface);display:flex;flex-direction:column;justify-content:space-between}\n.strip-svg-wrap{width:100%;padding:6px 8px 4px}\n\n/* 颗粒详情底部状态栏（显微镜放大镜检视卡） */\n.chip-inspector{display:grid;grid-template-columns:64px 1fr auto;gap:12px;align-items:center;\n  padding:9px 14px;background:var(--paper);border-top:1px solid var(--line);font-size:11.5px}\n.chip-zoom-box{width:64px;height:52px;border-radius:7px;border:1px solid var(--line-2);background:#16191c;overflow:hidden;position:relative;flex-shrink:0}\n.chip-zoom-box canvas{width:100%;height:100%;display:block}\n.chip-meta{display:flex;flex-direction:column;gap:2px;min-width:0}\n.chip-meta-top{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.chip-meta-top b{font-size:12px;color:var(--ink)}\n.chip-probs{display:flex;gap:8px;flex-wrap:wrap;font-size:11px;color:var(--ink-3);font-family:var(--mono)}\n.chip-badge{display:inline-flex;align-items:center;gap:4px;font-size:10.5px;font-weight:600;padding:1px 7px;border-radius:99px}\n.chip-badge.caving{background:var(--red-l);color:var(--red);border:1px solid rgba(180,72,60,.3)}\n.chip-badge.normal{background:var(--green-l);color:var(--green);border:1px solid rgba(47,125,91,.3)}\n.chip-badge.uv-hi{background:var(--amber-l);color:var(--amber);border:1px solid rgba(194,122,44,.35)}\n\n.btn-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}\n\n@media (max-width:960px){\n  .dual-workbench{grid-template-columns:1fr}\n  .tray-pane{border-right:0;border-bottom:1px solid var(--line)}\n}\n","enc":"text","size":14017},{"name":"demo/demo.js","data":"// ============================================================================\n// 录井 · 岩屑岩性自动识别（mudlog-cuttings-cls）交互式工作台逻辑\n// 白光与紫外荧光双模态岩屑细粒度识别与综合柱状图构建\n// ============================================================================\n(function () {\n  'use strict';\n\n  // 5 类细粒度岩性定义\n  const LITHOS = [\n    { id: 0, key: 'mud',   name: '泥岩',         en: 'Mudstone',          color: '#7d8790', rgb: [118, 126, 134], grainMm: [0.008, 0.030], round: 0.46 },\n    { id: 1, key: 'smud',  name: '粉砂质泥岩',   en: 'Silty Mudstone',    color: '#9ba89d', rgb: [148, 160, 150], grainMm: [0.032, 0.062], round: 0.54 },\n    { id: 2, key: 'msilt', name: '泥质粉砂岩',   en: 'Argillaceous Silt', color: '#c4ba97', rgb: [188, 178, 145], grainMm: [0.065, 0.115], round: 0.63 },\n    { id: 3, key: 'fsand', name: '细砂岩',       en: 'Fine Sandstone',    color: '#e0be6e', rgb: [216, 188, 128], grainMm: [0.130, 0.240], round: 0.76 },\n    { id: 4, key: 'lime',  name: '生物碎屑灰岩', en: 'Bioclastic Lime',   color: '#799ec2', rgb: [142, 164, 185], grainMm: [0.090, 0.210], round: 0.58 }\n  ];\n\n  // 2420m - 2490m 8 个典型储盖层深度样点定义（含真实岩性百分比、钻时 ROP、迟到时间、含油特征）\n  const DEPTH_LAYERS = [\n    {\n      depth: 2424, span: [2420, 2428], name: '暗灰泥岩盖层', tag: '无荧光', tagCls: 'oil-none',\n      rop: 3.6, lagMin: 32.8, comp: [78, 16, 6, 0, 0],\n      uvRatioBase: 0.0, uvHue: 210, uvBri: 0.08, oilType: '干层无显示'\n    },\n    {\n      depth: 2432, span: [2428, 2437], name: '粉砂质泥岩段', tag: '无荧光', tagCls: 'oil-none',\n      rop: 3.1, lagMin: 33.2, comp: [30, 52, 15, 3, 0],\n      uvRatioBase: 0.01, uvHue: 185, uvBri: 0.12, oilType: '干层无显示'\n    },\n    {\n      depth: 2442, span: [2437, 2447], name: '泥质粉砂过渡带', tag: '油迹级', tagCls: 'oil-trace',\n      rop: 2.4, lagMin: 33.8, comp: [12, 24, 48, 16, 0],\n      uvRatioBase: 0.08, uvHue: 72, uvBri: 0.48, oilType: '零星黄绿荧光'\n    },\n    {\n      depth: 2452, span: [2447, 2456], name: '细砂岩主力油层', tag: '油浸级', tagCls: 'oil-imm',\n      rop: 1.5, lagMin: 34.5, comp: [5, 7, 16, 72, 0],\n      uvRatioBase: 0.54, uvHue: 54, uvBri: 0.88, oilType: '亮黄金黄荧光·轻中质油'\n    },\n    {\n      depth: 2460, span: [2456, 2464], name: '含油细砂岩段', tag: '油斑级', tagCls: 'oil-spot',\n      rop: 1.8, lagMin: 35.0, comp: [8, 10, 24, 58, 0],\n      uvRatioBase: 0.28, uvHue: 64, uvBri: 0.76, oilType: '黄绿色荧光·中质原油'\n    },\n    {\n      depth: 2468, span: [2464, 2472], name: '生屑灰岩裂缝段', tag: '油斑级', tagCls: 'oil-spot',\n      rop: 2.7, lagMin: 35.5, comp: [10, 8, 10, 8, 64],\n      uvRatioBase: 0.22, uvHue: 46, uvBri: 0.82, oilType: '沿缝亮黄白荧光·轻质油'\n    },\n    {\n      depth: 2476, span: [2472, 2480], name: '细砂油水过渡带', tag: '油迹级', tagCls: 'oil-trace',\n      rop: 1.9, lagMin: 36.1, comp: [8, 12, 22, 54, 4],\n      uvRatioBase: 0.09, uvHue: 34, uvBri: 0.52, oilType: '暗褐橙斑点荧光·水洗稠化'\n    },\n    {\n      depth: 2485, span: [2480, 2490], name: '细砂岩底水层', tag: '无荧光', tagCls: 'oil-none',\n      rop: 1.7, lagMin: 36.8, comp: [6, 10, 18, 66, 0],\n      uvRatioBase: 0.005, uvHue: 205, uvBri: 0.10, oilType: '水层无荧光发光'\n    }\n  ];\n\n  // 状态管理\n  const state = {\n    step: 4,              // 0..4 对应 5 步流程\n    mode: 'ai',           // 'white' | 'uv' | 'ai'\n    splitScreen: false,   // 白光/荧光同框对比\n    showRuler: true,      // 粒径标尺与编号\n    depthIdx: 3,          // 默认选中 2452m 细砂岩主力油层\n    cavingPct: 12,        // 上部井壁掉块混样比例 (0..30%)\n    mudLevel: 0.15,       // 泥浆包裹污染度 (0..0.8)\n    uvThr: 0.32,          // 荧光有效分割阈值 (0.15..0.65)\n    cavingFilter: true,   // 启用邻深上下文掉块剔除算法\n    selectedChip: 7,      // 当前检视颗粒索引 (0..35)\n    hoverChip: -1,\n    scanTimer: null,\n    chips: [],            // 当前样盘 36 颗岩屑对象\n    layerStats: []        // 8 个深度层计算结果\n  };\n\n  // 固定种子伪随机生成器\n  function mulberry32(seed) {\n    let a = seed >>> 0;\n    return function () {\n      a |= 0; a = (a + 0x6D2B79F5) | 0;\n      let t = Math.imul(a ^ (a >>> 15), 1 | a);\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n\n  // 生成当前样盘的 36 颗多边形岩屑（6×6 网格扰动排布）\n  function buildTrayChips() {\n    const layer = DEPTH_LAYERS[state.depthIdx];\n    const rng = mulberry32(layer.depth * 131 + 17);\n    const cols = 6, rows = 6;\n    const W = 520, H = 440;\n    const padX = 48, padY = 46;\n    const cellW = (W - padX * 2) / cols;\n    const cellH = (H - padY * 2) / rows;\n\n    // 按当前深度真实岩性比例分配 36 颗原位颗粒岩性\n    const cdf = [];\n    let acc = 0;\n    for (let i = 0; i < 5; i++) {\n      acc += layer.comp[i];\n      cdf.push(acc / 100);\n    }\n\n    // 计算混入的上部泥岩/粉砂质泥岩掉块数量\n    const numCaving = layer.depth > 2435 ? Math.round(36 * (state.cavingPct / 100)) : 0;\n    const chips = [];\n\n    for (let r = 0; r < rows; r++) {\n      for (let c = 0; c < cols; c++) {\n        const idx = r * cols + c;\n        const cx = padX + (c + 0.5) * cellW + (rng() - 0.5) * 14;\n        const cy = padY + (r + 0.5) * cellH + (rng() - 0.5) * 12;\n\n        // 决定是否为上部井壁掉块（大块尖锐暗色泥岩）\n        const isCaving = (idx % 7 === 1 || idx % 9 === 4 || idx % 5 === 2) &&\n                         (chips.filter(x => x.isCaving).length < numCaving);\n\n        let trueLitho = 3;\n        if (isCaving) {\n          trueLitho = rng() < 0.78 ? 0 : 1; // 上部井壁坍塌掉块以暗色泥岩为主\n        } else {\n          const u = (idx + 0.35 + rng() * 0.3) / 36;\n          const uMod = (u + rng() * 0.18) % 1;\n          for (let k = 0; k < 5; k++) {\n            if (uMod <= cdf[k]) { trueLitho = k; break; }\n          }\n        }\n\n        const li = LITHOS[trueLitho];\n        const baseRad = isCaving ? (23 + rng() * 5) : (16 + rng() * 7.5);\n        const aspect = isCaving ? (0.62 + rng() * 0.25) : (0.74 + rng() * 0.24);\n        const angle = rng() * Math.PI * 2;\n\n        // 生成 9-11 个多边形顶点\n        const nVerts = isCaving ? 8 : 10;\n        const verts = [];\n        for (let v = 0; v < nVerts; v++) {\n          const theta = (v / nVerts) * Math.PI * 2;\n          const jag = isCaving ? (0.74 + rng() * 0.44) : (0.84 + rng() * 0.28);\n          const rx = Math.cos(theta) * baseRad * jag;\n          const ry = Math.sin(theta) * baseRad * aspect * jag;\n          const x = cx + rx * Math.cos(angle) - ry * Math.sin(angle);\n          const y = cy + rx * Math.sin(angle) + ry * Math.cos(angle);\n          verts.push([x, y]);\n        }\n\n        // 矿物颗粒粒径与圆度\n        const gMin = li.grainMm[0], gMax = li.grainMm[1];\n        const grainMm = gMin + rng() * (gMax - gMin);\n        const phi = -Math.log2(grainMm);\n        const roundness = isCaving ? (0.28 + rng() * 0.16) : Math.min(0.92, Math.max(0.35, li.round + (rng() - 0.5) * 0.16));\n\n        // 紫外荧光特征（细砂岩与生屑灰岩裂缝含油发光，泥岩/掉块不发光）\n        let rawUvCover = 0;\n        if (!isCaving && (trueLitho === 3 || trueLitho === 4 || trueLitho === 2)) {\n          const lithBoost = trueLitho === 3 ? 1.25 : (trueLitho === 4 ? 1.15 : 0.45);\n          rawUvCover = Math.min(0.95, Math.max(0, layer.uvRatioBase * lithBoost * (0.7 + rng() * 0.65)));\n        }\n        // 阈值与泥浆遮挡影响后的有效荧光占比\n        const mudMask = 1 - state.mudLevel * 0.62;\n        const thrFactor = Math.max(0, (rawUvCover * mudMask - (state.uvThr - 0.28) * 0.65));\n        const uvCover = Math.min(0.96, Math.max(0, thrFactor));\n\n        // AI 模型预测（泥浆污染度高时，细砂岩/泥质粉砂岩/粉砂质泥岩易发生混淆）\n        const probs = [0.02, 0.02, 0.02, 0.02, 0.02];\n        const cleanConf = Math.max(0.42, 0.91 - state.mudLevel * 0.48 - (rng() * 0.08));\n        probs[trueLitho] = cleanConf;\n        const rem = 1 - cleanConf;\n        // 泥浆包裹会把砂岩/粉砂岩往泥质方向拉偏\n        const mudShift = state.mudLevel * 0.35;\n        if (trueLitho === 3) {\n          probs[2] += rem * (0.55 + mudShift * 0.3);\n          probs[1] += rem * (0.28 + mudShift * 0.4);\n          probs[0] += rem * 0.12;\n          probs[4] += rem * 0.05;\n        } else if (trueLitho === 2) {\n          probs[1] += rem * (0.48 + mudShift * 0.4);\n          probs[3] += rem * (0.34 - mudShift * 0.2);\n          probs[0] += rem * 0.14;\n          probs[4] += rem * 0.04;\n        } else if (trueLitho === 1) {\n          probs[0] += rem * (0.52 + mudShift * 0.3);\n          probs[2] += rem * 0.36;\n          probs[3] += rem * 0.08;\n          probs[4] += rem * 0.04;\n        } else {\n          for (let k = 0; k < 5; k++) if (k !== trueLitho) probs[k] += rem / 4;\n        }\n        // 归一化概率并确定预测类别\n        const pSum = probs.reduce((a, b) => a + b, 0);\n        for (let k = 0; k < 5; k++) probs[k] = probs[k] / pSum;\n\n        // 当泥浆污染严重且随机数触发时产生细粒度误判\n        let predLitho = trueLitho;\n        if (state.mudLevel > 0.28 && rng() < (state.mudLevel - 0.15) * 0.55) {\n          if (trueLitho === 3) predLitho = 2;\n          else if (trueLitho === 2) predLitho = 1;\n          else if (trueLitho === 1) predLitho = 0;\n          else if (trueLitho === 4) predLitho = 2;\n          const tmp = probs[trueLitho];\n          probs[trueLitho] = probs[predLitho] * 0.85;\n          probs[predLitho] = tmp;\n        }\n\n        // 生成颗粒内部纹理斑点种子\n        const specks = [];\n        for (let s = 0; s < 14; s++) {\n          const sr = rng() * baseRad * 0.68;\n          const sa = rng() * Math.PI * 2;\n          specks.push({\n            dx: Math.cos(sa) * sr,\n            dy: Math.sin(sa) * sr * aspect,\n            sz: trueLitho === 3 ? (1.6 + rng() * 1.6) : (0.9 + rng() * 1.1),\n            br: rng(),\n            uv: s / 14 < uvCover * 1.25\n          });\n        }\n\n        chips.push({\n          id: idx + 1,\n          cx, cy, baseRad, aspect, angle, verts,\n          trueLitho, predLitho, probs,\n          isCaving,\n          filteredOut: isCaving && state.cavingFilter,\n          grainMm, phi, roundness,\n          uvCover,\n          uvHue: layer.uvHue + (rng() - 0.5) * 14,\n          uvBri: layer.uvBri,\n          areaWeight: baseRad * baseRad * aspect,\n          specks\n        });\n      }\n    }\n    state.chips = chips;\n  }\n\n\n  // 计算 8 个深度层的预测百分比与荧光级别\n  function computeLayerStats() {\n    state.layerStats = DEPTH_LAYERS.map((L, idx) => {\n      const compTrue = L.comp.slice();\n      const compPred = L.comp.slice();\n      // 未开启掉块剔除且深度>2435m时，泥岩比例偏高\n      const cavEffect = (!state.cavingFilter && L.depth > 2435) ? state.cavingPct * 0.65 : state.cavingPct * 0.08;\n      const mudEffect = state.mudLevel * 12;\n      compPred[0] = Math.min(92, Math.max(0, compTrue[0] + cavEffect + mudEffect * 0.4));\n      compPred[1] = Math.min(90, Math.max(0, compTrue[1] + mudEffect * 0.35));\n      compPred[3] = Math.max(0, compTrue[3] - cavEffect * 0.8 - mudEffect * 0.55);\n      compPred[2] = Math.max(0, compTrue[2] - cavEffect * 0.2 - mudEffect * 0.2);\n      const sum = compPred.reduce((a, b) => a + b, 0) || 1;\n      for (let k = 0; k < 5; k++) compPred[k] = +(compPred[k] / sum * 100).toFixed(1);\n\n      const mudMask = 1 - state.mudLevel * 0.55;\n      const uvArea = Math.max(0, Math.min(85, (L.uvRatioBase * 100 * mudMask) - (state.uvThr - 0.30) * 35));\n      let grade = '无荧光', gradeEn = 'No Show', gradeCls = 'oil-none';\n      if (uvArea >= 35) { grade = '油浸级'; gradeEn = 'Oil-Immersed'; gradeCls = 'oil-imm'; }\n      else if (uvArea >= 15) { grade = '油斑级'; gradeEn = 'Oil-Stained'; gradeCls = 'oil-spot'; }\n      else if (uvArea >= 3) { grade = '油迹级'; gradeEn = 'Oil-Trace'; gradeCls = 'oil-trace'; }\n\n      return { layer: L, idx, compTrue, compPred, uvArea, grade, gradeEn, gradeCls };\n    });\n  }\n\n  // 渲染左侧 8 层深度列表\n  function renderDepthList() {\n    const box = document.getElementById('depthList');\n    if (!box) return;\n    box.innerHTML = state.layerStats.map((st, i) => {\n      const L = st.layer;\n      const on = i === state.depthIdx ? ' on' : '';\n      return `<button type=\"button\" class=\"depth-item${on}\" data-d=\"${i}\">\n        <span class=\"d-m\">${L.depth}.0 m</span>\n        <span class=\"d-name\">${L.name}</span>\n        <span class=\"d-tag ${st.gradeCls}\">${st.grade}</span>\n      </button>`;\n    }).join('');\n    box.querySelectorAll('.depth-item').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.depthIdx = +btn.dataset.d;\n        updateAll();\n      });\n    });\n  }\n\n  // 绘制单颗岩屑在给定 Canvas 上下文\n  function drawSingleChip(ctx, ch, mode, offsetX) {\n    ctx.save();\n    ctx.translate(offsetX || 0, 0);\n    ctx.beginPath();\n    ch.verts.forEach((p, i) => i === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1]));\n    ctx.closePath();\n\n    const li = LITHOS[ch.trueLitho];\n    if (mode === 'uv') {\n      ctx.fillStyle = '#111622';\n      ctx.fill();\n      if (ch.uvCover > 0.02) {\n        const g = ctx.createRadialGradient(ch.cx, ch.cy, 2, ch.cx, ch.cy, ch.baseRad);\n        const alpha = Math.min(0.95, ch.uvCover * 1.35);\n        g.addColorStop(0, `hsla(${ch.uvHue}, 95%, 64%, ${alpha})`);\n        g.addColorStop(0.7, `hsla(${ch.uvHue + 12}, 90%, 48%, ${alpha * 0.65})`);\n        g.addColorStop(1, 'rgba(15,22,36,0.1)');\n        ctx.fillStyle = g;\n        ctx.fill();\n      }\n      ctx.strokeStyle = ch.uvCover > 0.12 ? `hsla(${ch.uvHue}, 90%, 60%, 0.8)` : 'rgba(120,140,170,0.28)';\n      ctx.lineWidth = 1.1;\n      ctx.stroke();\n    } else {\n      // 白光或 AI 模式底色\n      const [r, g, b] = li.rgb;\n      const mudMix = state.mudLevel * 0.45;\n      const mr = Math.round(r * (1 - mudMix) + 108 * mudMix);\n      const mg = Math.round(g * (1 - mudMix) + 102 * mudMix);\n      const mb = Math.round(b * (1 - mudMix) + 92 * mudMix);\n      ctx.fillStyle = `rgb(${mr},${mg},${mb})`;\n      ctx.fill();\n\n      // 颗粒表面矿物纹理斑点\n      ch.specks.forEach(sp => {\n        ctx.fillStyle = sp.br > 0.5 ? 'rgba(255,250,235,0.34)' : 'rgba(40,38,32,0.28)';\n        ctx.beginPath();\n        ctx.arc(ch.cx + sp.dx, ch.cy + sp.dy, sp.sz, 0, Math.PI * 2);\n        ctx.fill();\n      });\n\n      if (mode === 'ai') {\n        const predLi = LITHOS[ch.predLitho];\n        if (ch.filteredOut) {\n          ctx.strokeStyle = '#b4483c';\n          ctx.lineWidth = 2.2;\n          ctx.setLineDash([4, 3]);\n          ctx.stroke();\n          ctx.setLineDash([]);\n          // 掉块剔除叉号\n          ctx.strokeStyle = 'rgba(180,72,60,0.85)';\n          ctx.beginPath();\n          ctx.moveTo(ch.cx - 8, ch.cy - 8); ctx.lineTo(ch.cx + 8, ch.cy + 8);\n          ctx.moveTo(ch.cx + 8, ch.cy - 8); ctx.lineTo(ch.cx - 8, ch.cy + 8);\n          ctx.stroke();\n        } else {\n          ctx.strokeStyle = predLi.color;\n          ctx.lineWidth = 2.2;\n          ctx.stroke();\n          if (ch.uvCover > 0.12 && state.step >= 3) {\n            ctx.fillStyle = 'rgba(56, 229, 77, 0.26)';\n            ctx.beginPath();\n            ctx.arc(ch.cx, ch.cy, ch.baseRad * 0.55 * ch.uvCover, 0, Math.PI * 2);\n            ctx.fill();\n          }\n        }\n      } else {\n        ctx.strokeStyle = 'rgba(30,35,40,0.45)';\n        ctx.lineWidth = 1;\n        ctx.stroke();\n      }\n    }\n\n    // 选中或悬停高亮框\n    const isSel = (ch.id - 1) === state.selectedChip;\n    const isHov = (ch.id - 1) === state.hoverChip;\n    if (isSel || isHov) {\n      ctx.strokeStyle = isSel ? '#f59e0b' : '#38bdf8';\n      ctx.lineWidth = isSel ? 2.6 : 1.8;\n      ctx.beginPath();\n      ctx.arc(ch.cx, ch.cy, ch.baseRad + 5, 0, Math.PI * 2);\n      ctx.stroke();\n    }\n\n    if (state.showRuler && !state.splitScreen) {\n      ctx.fillStyle = mode === 'uv' ? 'rgba(230,240,255,0.82)' : 'rgba(20,24,28,0.82)';\n      ctx.font = '600 9.5px ui-monospace, monospace';\n      ctx.textAlign = 'center';\n      ctx.fillText(`#${ch.id < 10 ? '0' + ch.id : ch.id}`, ch.cx, ch.cy + 3);\n    }\n    ctx.restore();\n  }\n\n  // 渲染样盘主画布\n  function renderTrayCanvas() {\n    const cvs = document.getElementById('trayCanvas');\n    if (!cvs) return;\n    const ctx = cvs.getContext('2d');\n    const W = cvs.width, H = cvs.height;\n    ctx.clearRect(0, 0, W, H);\n\n    if (state.splitScreen) {\n      // 左半白光，右半 UV\n      ctx.fillStyle = '#e7e2d5';\n      ctx.fillRect(0, 0, W / 2, H);\n      ctx.fillStyle = '#0b101b';\n      ctx.fillRect(W / 2, 0, W / 2, H);\n\n      ctx.save();\n      ctx.beginPath(); ctx.rect(0, 0, W / 2, H); ctx.clip();\n      state.chips.forEach(ch => drawSingleChip(ctx, ch, 'white', 0));\n      ctx.restore();\n\n      ctx.save();\n      ctx.beginPath(); ctx.rect(W / 2, 0, W / 2, H); ctx.clip();\n      state.chips.forEach(ch => drawSingleChip(ctx, ch, 'uv', 0));\n      ctx.restore();\n\n      ctx.strokeStyle = '#f59e0b';\n      ctx.lineWidth = 2;\n      ctx.beginPath(); ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, H); ctx.stroke();\n\n      ctx.fillStyle = 'rgba(20,24,28,0.78)';\n      ctx.fillRect(10, 10, 128, 22);\n      ctx.fillStyle = '#fff';\n      ctx.font = '600 11px sans-serif';\n      ctx.fillText('左：D65 白光显微', 18, 25);\n\n      ctx.fillStyle = 'rgba(18,97,90,0.88)';\n      ctx.fillRect(W / 2 + 10, 10, 142, 22);\n      ctx.fillStyle = '#fff';\n      ctx.fillText('右：365nm 紫外荧光', W / 2 + 18, 25);\n    } else {\n      ctx.fillStyle = state.mode === 'uv' ? '#0b101b' : '#ebe6da';\n      ctx.fillRect(0, 0, W, H);\n      // 暗箱网格与标尺\n      ctx.strokeStyle = state.mode === 'uv' ? 'rgba(80,110,150,0.14)' : 'rgba(60,55,45,0.09)';\n      ctx.lineWidth = 1;\n      for (let x = 40; x < W; x += 40) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke(); }\n      for (let y = 40; y < H; y += 40) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke(); }\n\n      state.chips.forEach(ch => drawSingleChip(ctx, ch, state.mode, 0));\n\n      // 右下角 1 mm 显微比例尺\n      ctx.fillStyle = state.mode === 'uv' ? 'rgba(15,23,38,0.85)' : 'rgba(255,252,245,0.88)';\n      ctx.fillRect(W - 118, H - 30, 108, 22);\n      ctx.strokeStyle = state.mode === 'uv' ? '#38bdf8' : '#12615a';\n      ctx.lineWidth = 2;\n      ctx.beginPath();\n      ctx.moveTo(W - 108, H - 16); ctx.lineTo(W - 58, H - 16);\n      ctx.moveTo(W - 108, H - 20); ctx.lineTo(W - 108, H - 12);\n      ctx.moveTo(W - 58, H - 20); ctx.lineTo(W - 58, H - 12);\n      ctx.stroke();\n      ctx.fillStyle = state.mode === 'uv' ? '#e2e8f0' : '#1f2937';\n      ctx.font = '600 10px ui-monospace, monospace';\n      ctx.fillText('0.50 mm', W - 52, H - 13);\n    }\n  }\n\n  // 渲染单颗岩屑放大镜与检视栏\n  function renderChipInspector() {\n    const ch = state.chips[state.selectedChip] || state.chips[0];\n    if (!ch) return;\n    const zc = document.getElementById('zoomCanvas');\n    if (zc) {\n      const ctx = zc.getContext('2d');\n      const W = zc.width, H = zc.height;\n      ctx.clearRect(0, 0, W, H);\n      // 左半白光放大，右半荧光放大\n      ctx.fillStyle = '#eae4d7';\n      ctx.fillRect(0, 0, W / 2, H);\n      ctx.fillStyle = '#0c1220';\n      ctx.fillRect(W / 2, 0, W / 2, H);\n\n      [0, 1].forEach(side => {\n        ctx.save();\n        ctx.beginPath();\n        ctx.rect(side * (W / 2), 0, W / 2, H);\n        ctx.clip();\n        ctx.translate(side * (W / 2) + W / 4, H / 2);\n        ctx.scale(1.15, 1.15);\n        ctx.translate(-ch.cx, -ch.cy);\n        drawSingleChip(ctx, ch, side === 0 ? 'white' : 'uv', 0);\n        ctx.restore();\n      });\n      ctx.strokeStyle = 'rgba(150,150,150,0.4)';\n      ctx.beginPath(); ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, H); ctx.stroke();\n    }\n\n    const trueLi = LITHOS[ch.trueLitho];\n    const predLi = LITHOS[ch.predLitho];\n    const hdr = document.getElementById('chipHeader');\n    if (hdr) {\n      const cavTag = ch.isCaving\n        ? `<span class=\"chip-badge caving\">${ch.filteredOut ? '上部掉块 (已剔除)' : '上部掉块混入'}</span>`\n        : `<span class=\"chip-badge normal\">原位地层颗粒</span>`;\n      const uvPct = Math.round(ch.uvCover * 100);\n      const uvTag = uvPct > 8\n        ? `<span class=\"chip-badge uv-hi\">UV 发光 ${uvPct}%</span>`\n        : `<span class=\"chip-badge\">无明显荧光 (${uvPct}%)</span>`;\n      hdr.innerHTML = `<b>颗粒 #${ch.id < 10 ? '0' + ch.id : ch.id} · 预测：${predLi.name} (${predLi.en})</b> ${cavTag} ${uvTag}`;\n    }\n    const specs = document.getElementById('chipSpecs');\n    if (specs) {\n      const [r, g, b] = trueLi.rgb;\n      specs.textContent = `等效粒径 D = ${ch.grainMm.toFixed(3)} mm (Φ = ${ch.phi.toFixed(2)}) · 圆度 ${ch.roundness.toFixed(2)} · 校准 RGB(${r},${g},${b}) · 真实类别：${trueLi.name}`;\n    }\n    const probsEl = document.getElementById('chipProbs');\n    if (probsEl) {\n      probsEl.innerHTML = '预测概率：' + LITHOS.map((l, k) => {\n        const p = (ch.probs[k] * 100).toFixed(1) + '%';\n        return k === ch.predLitho ? `<b>${l.name} ${p}</b>` : `${l.name} ${p}`;\n      }).join(' | ');\n    }\n    const cntEl = document.getElementById('chipCountInfo');\n    if (cntEl) {\n      const nDrop = state.chips.filter(x => x.filteredOut).length;\n      const nValid = state.chips.length - nDrop;\n      cntEl.textContent = `有效颗粒 ${nValid} / 掉块剔除 ${nDrop}`;\n    }\n  }\n\n  // 渲染右侧 2420m–2490m 随钻录井岩性百分比与荧光综合柱状图 SVG\n  function renderStripSvg() {\n    const svg = document.getElementById('stripSvg');\n    if (!svg) return;\n    let html = `\n      <rect x=\"0\" y=\"0\" width=\"430\" height=\"430\" fill=\"#fbf9f4\"/>\n      <text x=\"10\" y=\"18\" font-size=\"11\" font-weight=\"700\" fill=\"#1b242c\">深度(m)</text>\n      <text x=\"64\" y=\"18\" font-size=\"11\" font-weight=\"700\" fill=\"#1b242c\">钻时ROP</text>\n      <text x=\"128\" y=\"18\" font-size=\"11\" font-weight=\"700\" fill=\"#1b242c\">岩性百分比剖面 (100%)</text>\n      <text x=\"295\" y=\"18\" font-size=\"11\" font-weight=\"700\" fill=\"#1b242c\">荧光面积%</text>\n      <text x=\"366\" y=\"18\" font-size=\"11\" font-weight=\"700\" fill=\"#1b242c\">含油级别</text>\n      <line x1=\"6\" y1=\"24\" x2=\"424\" y2=\"24\" stroke=\"#d5cfc2\" stroke-width=\"1\"/>\n    `;\n\n    const topY = 30, rowH = 48;\n    // 钻时折线坐标点\n    const ropPts = [];\n\n    state.layerStats.forEach((st, i) => {\n      const L = st.layer;\n      const y = topY + i * rowH;\n      const isCur = i === state.depthIdx;\n\n      if (isCur) {\n        html += `<rect x=\"4\" y=\"${y}\" width=\"422\" height=\"${rowH - 2}\" rx=\"4\" fill=\"rgba(18,97,90,0.10)\" stroke=\"#12615a\" stroke-width=\"1.5\"/>`;\n      } else {\n        html += `<rect x=\"4\" y=\"${y}\" width=\"422\" height=\"${rowH - 2}\" fill=\"${i % 2 === 0 ? '#ffffff' : '#f6f3ec'}\"/>`;\n      }\n\n      // 深度文字\n      html += `<text x=\"10\" y=\"${y + 19}\" font-size=\"11\" font-family=\"ui-monospace,monospace\" font-weight=\"700\" fill=\"${isCur ? '#12615a' : '#2c353d'}\">${L.depth}.0m</text>`;\n      html += `<text x=\"10\" y=\"${y + 34}\" font-size=\"9.5\" fill=\"#6b747c\">${L.span[0]}-${L.span[1]}</text>`;\n\n      // 钻时点 (1.0 - 4.0 min/m -> x: 64..116)\n      const rx = 64 + ((L.rop - 1.0) / 3.2) * 48;\n      const ry = y + rowH / 2;\n      ropPts.push(`${rx.toFixed(1)},${ry.toFixed(1)}`);\n      html += `<circle cx=\"${rx.toFixed(1)}\" cy=\"${ry.toFixed(1)}\" r=\"3\" fill=\"#3a6ea5\"/>`;\n      html += `<text x=\"${rx.toFixed(1)}\" y=\"${ry - 6}\" font-size=\"9\" font-family=\"ui-monospace,monospace\" fill=\"#3a6ea5\" text-anchor=\"middle\">${L.rop}</text>`;\n\n      // 岩性百分比堆叠条 (x: 126, width: 158)\n      let curX = 126;\n      const barW = 158;\n      for (let k = 0; k < 5; k++) {\n        const w = (st.compPred[k] / 100) * barW;\n        if (w > 0.4) {\n          html += `<rect x=\"${curX.toFixed(1)}\" y=\"${y + 7}\" width=\"${w.toFixed(1)}\" height=\"${rowH - 16}\" fill=\"${LITHOS[k].color}\" stroke=\"rgba(255,255,255,0.5)\" stroke-width=\"0.5\"/>`;\n          if (w > 24) {\n            html += `<text x=\"${(curX + w / 2).toFixed(1)}\" y=\"${y + 27}\" font-size=\"9.5\" font-family=\"ui-monospace,monospace\" fill=\"#182026\" text-anchor=\"middle\" font-weight=\"600\">${Math.round(st.compPred[k])}%</text>`;\n          }\n          curX += w;\n        }\n      }\n\n      // 荧光面积条 (x: 294, maxW: 62)\n      const uvW = (st.uvArea / 70) * 60;\n      html += `<rect x=\"294\" y=\"${y + 14}\" width=\"60\" height=\"16\" rx=\"3\" fill=\"#e9e4d8\"/>`;\n      if (uvW > 0.5) {\n        const uvCol = st.uvArea > 30 ? '#eab308' : (st.uvArea > 12 ? '#84cc16' : '#38bdf8');\n        html += `<rect x=\"294\" y=\"${y + 14}\" width=\"${Math.min(60, uvW).toFixed(1)}\" height=\"16\" rx=\"3\" fill=\"${uvCol}\"/>`;\n      }\n      html += `<text x=\"324\" y=\"${y + 26}\" font-size=\"9.5\" font-family=\"ui-monospace,monospace\" fill=\"#1f2937\" text-anchor=\"middle\" font-weight=\"700\">${st.uvArea.toFixed(1)}%</text>`;\n\n      // 含油级别胶囊\n      const badgeBg = st.grade === '油浸级' ? '#fef3c7' : (st.grade === '油斑级' ? '#ecfccb' : (st.grade === '油迹级' ? '#e0f2fe' : '#f1f5f9'));\n      const badgeFg = st.grade === '油浸级' ? '#b45309' : (st.grade === '油斑级' ? '#3f6212' : (st.grade === '油迹级' ? '#0369a1' : '#64748b'));\n      html += `<rect x=\"364\" y=\"${y + 12}\" width=\"56\" height=\"22\" rx=\"4\" fill=\"${badgeBg}\" stroke=\"${badgeFg}\" stroke-opacity=\"0.35\"/>`;\n      html += `<text x=\"392\" y=\"${y + 27}\" font-size=\"10.5\" font-weight=\"700\" fill=\"${badgeFg}\" text-anchor=\"middle\">${st.grade}</text>`;\n\n      // 整行点击热区\n      html += `<rect x=\"4\" y=\"${y}\" width=\"422\" height=\"${rowH - 2}\" fill=\"transparent\" style=\"cursor:pointer\" data-strip-idx=\"${i}\"/>`;\n    });\n\n    html += `<polyline points=\"${ropPts.join(' ')}\" fill=\"none\" stroke=\"#3a6ea5\" stroke-width=\"1.6\"/>`;\n    svg.innerHTML = html;\n\n    svg.querySelectorAll('[data-strip-idx]').forEach(el => {\n      el.addEventListener('click', () => {\n        state.depthIdx = +el.getAttribute('data-strip-idx');\n        updateAll();\n      });\n    });\n  }\n\n  // 渲染底部两张辅助分析 SVG（左：粒径分布与组分对比；右：5×5混淆矩阵与荧光色度图版）\n  function renderBottomCharts() {\n    const gSvg = document.getElementById('grainSvg');\n    const st = state.layerStats[state.depthIdx];\n    if (gSvg && st) {\n      // 统计当前样盘有效颗粒在 5 个粒径区间的频数\n      const bins = [\n        { label: '<0.03 泥级', min: 0, max: 0.031, c: 0, col: '#7d8790' },\n        { label: '0.03-0.06 细粉', min: 0.031, max: 0.063, c: 0, col: '#9ba89d' },\n        { label: '0.06-0.12 粗粉', min: 0.063, max: 0.125, c: 0, col: '#c4ba97' },\n        { label: '0.12-0.20 细砂', min: 0.125, max: 0.200, c: 0, col: '#e0be6e' },\n        { label: '>0.20 中细砂', min: 0.200, max: 1.0, c: 0, col: '#d49b4b' }\n      ];\n      const valid = state.chips.filter(x => !x.filteredOut);\n      valid.forEach(ch => {\n        for (const b of bins) {\n          if (ch.grainMm >= b.min && ch.grainMm < b.max) { b.c++; break; }\n        }\n      });\n      const maxC = Math.max(8, ...bins.map(b => b.c));\n\n      let h = `<text x=\"12\" y=\"18\" font-size=\"11\" font-weight=\"700\" fill=\"#2c353d\">有效颗粒等效粒径分布 (mm)</text>`;\n      bins.forEach((b, i) => {\n        const x = 18 + i * 44;\n        const bh = (b.c / maxC) * 125;\n        const y = 165 - bh;\n        h += `<rect x=\"${x}\" y=\"${y.toFixed(1)}\" width=\"30\" height=\"${bh.toFixed(1)}\" rx=\"3\" fill=\"${b.col}\"/>`;\n        h += `<text x=\"${x + 15}\" y=\"${(y - 5).toFixed(1)}\" font-size=\"10\" font-family=\"ui-monospace,monospace\" text-anchor=\"middle\" fill=\"#1b242c\" font-weight=\"700\">${b.c}</text>`;\n        h += `<text x=\"${x + 15}\" y=\"182\" font-size=\"8.8\" text-anchor=\"middle\" fill=\"#5c6670\">${b.label.split(' ')[1]}</text>`;\n        h += `<text x=\"${x + 15}\" y=\"194\" font-size=\"8.2\" font-family=\"ui-monospace,monospace\" text-anchor=\"middle\" fill=\"#7c858e\">${b.label.split(' ')[0]}</text>`;\n      });\n\n      // 右侧：真实比例 vs AI预测比例对比条\n      h += `<line x1=\"242\" y1=\"12\" x2=\"242\" y2=\"210\" stroke=\"#e2ddd2\"/>`;\n      h += `<text x=\"254\" y=\"18\" font-size=\"11\" font-weight=\"700\" fill=\"#2c353d\">真实 vs AI 岩性组分 (%)</text>`;\n      LITHOS.forEach((l, k) => {\n        const y = 34 + k * 35;\n        const tVal = st.compTrue[k];\n        const pVal = st.compPred[k];\n        h += `<text x=\"254\" y=\"${y + 10}\" font-size=\"9.5\" fill=\"#2c353d\" font-weight=\"600\">${l.name}</text>`;\n        h += `<rect x=\"316\" y=\"${y}\" width=\"${(tVal * 0.85).toFixed(1)}\" height=\"8\" rx=\"2\" fill=\"#94a3b8\"/>`;\n        h += `<rect x=\"316\" y=\"${y + 10}\" width=\"${(pVal * 0.85).toFixed(1)}\" height=\"8\" rx=\"2\" fill=\"${l.color}\"/>`;\n        h += `<text x=\"412\" y=\"${y + 14}\" font-size=\"9\" font-family=\"ui-monospace,monospace\" text-anchor=\"end\" fill=\"#1e293b\">${pVal.toFixed(0)}%</text>`;\n      });\n      h += `<text x=\"254\" y=\"214\" font-size=\"9\" fill=\"#64748b\">上灰条：地层真值 | 下彩条：AI归位统计</text>`;\n      gSvg.innerHTML = h;\n    }\n\n    const mSvg = document.getElementById('matrixUvSvg');\n    if (mSvg && st) {\n      const accDiag = Math.max(72, Math.round(94 - state.mudLevel * 22));\n      const off1 = Math.round((100 - accDiag) * 0.65);\n      const off2 = 100 - accDiag - off1;\n      const names = ['泥岩', '粉砂泥', '泥粉砂', '细砂', '灰岩'];\n      let h = `<text x=\"10\" y=\"16\" font-size=\"10.5\" font-weight=\"700\" fill=\"#2c353d\">5×5 细粒度分类混淆率(%)</text>`;\n      for (let r = 0; r < 5; r++) {\n        h += `<text x=\"44\" y=\"${45 + r * 32}\" font-size=\"9\" text-anchor=\"end\" fill=\"#475569\">${names[r]}</text>`;\n        for (let c = 0; c < 5; c++) {\n          let v = 0;\n          if (r === c) v = accDiag + (r === 4 ? 3 : 0);\n          else if (Math.abs(r - c) === 1 && r < 4 && c < 4) v = off1;\n          else v = Math.max(0, Math.round(off2 / 3));\n          const bg = r === c ? `rgba(18,97,90,${0.2 + v / 130})` : (v > 4 ? `rgba(194,122,44,${v / 45})` : '#f5f2ea');\n          const fg = (r === c && v > 60) ? '#ffffff' : '#1e293b';\n          const x = 48 + c * 32, y = 30 + r * 32;\n          h += `<rect x=\"${x}\" y=\"${y}\" width=\"30\" height=\"28\" rx=\"3\" fill=\"${bg}\"/>`;\n          h += `<text x=\"${x + 15}\" y=\"${y + 18}\" font-size=\"9\" font-family=\"ui-monospace,monospace\" text-anchor=\"middle\" fill=\"${fg}\" font-weight=\"600\">${v}</text>`;\n        }\n      }\n      // 右侧 UV 荧光色度-亮度原油性质判别图版\n      h += `<line x1=\"220\" y1=\"12\" x2=\"220\" y2=\"210\" stroke=\"#e2ddd2\"/>`;\n      h += `<text x=\"230\" y=\"16\" font-size=\"10.5\" font-weight=\"700\" fill=\"#2c353d\">UV 荧光色度油质图版</text>`;\n      h += `<rect x=\"232\" y=\"28\" width=\"176\" height=\"152\" rx=\"4\" fill=\"#0f172a\" stroke=\"#334155\"/>`;\n      // 4 个油质分区框\n      h += `<rect x=\"240\" y=\"36\" width=\"76\" height=\"62\" rx=\"3\" fill=\"rgba(56,189,248,0.16)\" stroke=\"#38bdf8\" stroke-dasharray=\"3 2\"/>`;\n      h += `<text x=\"278\" y=\"68\" font-size=\"9\" fill=\"#7dd3fc\" text-anchor=\"middle\">凝析油/轻质油(亮蓝白)</text>`;\n      h += `<rect x=\"322\" y=\"36\" width=\"78\" height=\"62\" rx=\"3\" fill=\"rgba(250,204,21,0.20)\" stroke=\"#facc15\" stroke-dasharray=\"3 2\"/>`;\n      h += `<text x=\"361\" y=\"68\" font-size=\"9\" fill=\"#fde047\" text-anchor=\"middle\">中轻质主力油(亮黄金黄)</text>`;\n      h += `<rect x=\"322\" y=\"106\" width=\"78\" height=\"64\" rx=\"3\" fill=\"rgba(234,88,12,0.18)\" stroke=\"#fb923c\" stroke-dasharray=\"3 2\"/>`;\n      h += `<text x=\"361\" y=\"140\" font-size=\"9\" fill=\"#fdba74\" text-anchor=\"middle\">稠油/水洗油(暗褐橙)</text>`;\n      h += `<rect x=\"240\" y=\"106\" width=\"76\" height=\"64\" rx=\"3\" fill=\"rgba(148,163,184,0.12)\" stroke=\"#64748b\" stroke-dasharray=\"3 2\"/>`;\n      h += `<text x=\"278\" y=\"140\" font-size=\"9\" fill=\"#94a3b8\" text-anchor=\"middle\">干层/底水层(无发光)</text>`;\n\n      // 当前深度层落点\n      const L = st.layer;\n      let px = 278, py = 140;\n      if (st.uvArea >= 3) {\n        px = L.uvHue < 42 ? 365 : (L.uvHue < 75 ? 355 : 278);\n        py = 170 - L.uvBri * 120;\n      }\n      h += `<circle cx=\"${px}\" cy=\"${py}\" r=\"7\" fill=\"#22c55e\" stroke=\"#ffffff\" stroke-width=\"2\"/>`;\n      h += `<text x=\"320\" y=\"198\" font-size=\"9.5\" fill=\"#1e293b\" text-anchor=\"middle\" font-weight=\"600\">当前层：${L.oilType}</text>`;\n      mSvg.innerHTML = h;\n    }\n  }\n\n  // 更新 KPI、顶栏胶囊与底部专业解读\n  function renderStatusAndKpis() {\n    const st = state.layerStats[state.depthIdx];\n    const L = st.layer;\n    const valid = state.chips.filter(x => !x.filteredOut);\n    const correct = valid.filter(x => x.trueLitho === x.predLitho).length;\n    const acc = valid.length ? ((correct / valid.length) * 100).toFixed(1) : '90.0';\n\n    let maeSum = 0;\n    for (let k = 0; k < 5; k++) maeSum += Math.abs(st.compTrue[k] - st.compPred[k]);\n    const mae = (maeSum / 5).toFixed(1);\n\n    document.getElementById('pillDepth').innerHTML = `<i></i><span>当前迟到归位深度：${L.depth}.0 m (${L.name})</span>`;\n    document.getElementById('pillOil').innerHTML = `<i></i><span>荧光定级：${st.grade}（${L.oilType}）</span>`;\n    document.getElementById('pillStatus').innerHTML = `<i></i><span>${state.cavingFilter ? '掉块剔除已开启' : '未剔除上部掉块'} · 组分 MAE ${mae}%</span>`;\n    document.getElementById('lagBadge').textContent = `迟到时间 Δt_lag = ${L.lagMin} min · 钻时 ROP = ${L.rop} min/m`;\n\n    document.getElementById('kpiAcc').innerHTML = `${acc}<small>%</small>`;\n    document.getElementById('kpiMae').innerHTML = `${mae}<small>%</small>`;\n    document.getElementById('kpiMaeBox').className = +mae <= 3.5 ? 'kpi ok' : 'kpi warn';\n    document.getElementById('kpiUvArea').innerHTML = `${st.uvArea.toFixed(1)}<small>%</small>`;\n    document.getElementById('kpiGrade').innerHTML = `${st.grade}<small>${st.gradeEn}</small>`;\n    document.getElementById('kpiGradeDesc').textContent = L.oilType;\n    document.getElementById('grainHint').textContent = `深度 ${L.depth}.0m 统计`;\n\n    const stepTexts = [\n      `<b>STEP 01 标准暗箱双模态采图</b>：在 D65 标准白光与 365nm 紫外激发光下同步采集振动筛湿样盘图像，利用内置色卡消除照明色偏。当前深度 <b>${L.depth}.0m (${L.name})</b>。`,\n      `<b>STEP 02 前景分割与伪影剔除</b>：将样盘拆解为 36 颗独立岩屑实例掩码，自动剥离金属网筛背景与镜面水膜反光点。当前泥浆包裹度 <b>${state.mudLevel.toFixed(2)}</b>。`,\n      `<b>STEP 03 细粒度纹理与粒径协同</b>：联合颜色纹理与颗粒等效粒径 Φ 区分过渡岩性，单颗粒识别准确率 <b>${acc}%</b>。`,\n      `<b>STEP 04 紫外荧光定量含油分级</b>：在 365nm 紫外通道统计有效发光像素面积占比为 <b>${st.uvArea.toFixed(1)}%</b>，自动定级为 <b>${st.grade}（${L.oilType}）</b>。`,\n      `<b>STEP 05 迟到深度归位与掉块剔除</b>：结合泥浆泵排量计算的迟到时间（<b>${L.lagMin} min</b>）归位真实深度，${state.cavingFilter ? '已通过上下文突变检测剔除上部井壁暗色泥岩掉块' : '当前关闭掉块剔除，混入的上部泥岩掉块导致储层砂岩比例被低估'}，组分百分比 MAE 为 <b>${mae}%</b>。`\n    ];\n    document.getElementById('insightText').innerHTML = stepTexts[state.step] || stepTexts[4];\n  }\n\n  function updateAll() {\n    computeLayerStats();\n    buildTrayChips();\n    renderDepthList();\n    renderTrayCanvas();\n    renderChipInspector();\n    renderStripSvg();\n    renderBottomCharts();\n    renderStatusAndKpis();\n  }\n\n  // 事件绑定\n  function bindEvents() {\n    document.querySelectorAll('#stepper button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.step = +btn.dataset.step;\n        document.querySelectorAll('#stepper button').forEach((b, i) => {\n          b.classList.toggle('on', i === state.step);\n          b.classList.toggle('done', i < state.step);\n        });\n        if (state.step === 0) state.mode = 'white';\n        else if (state.step === 3) state.mode = 'uv';\n        else state.mode = 'ai';\n        document.querySelectorAll('#segMode button').forEach(b => b.classList.toggle('on', b.dataset.mode === state.mode));\n        updateAll();\n      });\n    });\n\n    document.querySelectorAll('#segMode button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.mode = btn.dataset.mode;\n        document.querySelectorAll('#segMode button').forEach(b => b.classList.toggle('on', b === btn));\n        updateAll();\n      });\n    });\n\n    document.getElementById('chkSplit').addEventListener('change', e => {\n      state.splitScreen = e.target.checked;\n      renderTrayCanvas();\n    });\n    document.getElementById('chkRuler').addEventListener('change', e => {\n      state.showRuler = e.target.checked;\n      renderTrayCanvas();\n    });\n    document.getElementById('rngCaving').addEventListener('input', e => {\n      state.cavingPct = +e.target.value;\n      document.getElementById('outCaving').textContent = state.cavingPct + '%';\n      updateAll();\n    });\n    document.getElementById('rngMud').addEventListener('input', e => {\n      state.mudLevel = +e.target.value;\n      document.getElementById('outMud').textContent = state.mudLevel.toFixed(2);\n      updateAll();\n    });\n    document.getElementById('rngUvThr').addEventListener('input', e => {\n      state.uvThr = +e.target.value;\n      document.getElementById('outUvThr').textContent = state.uvThr.toFixed(2);\n      updateAll();\n    });\n    document.getElementById('chkCavingFilter').addEventListener('change', e => {\n      state.cavingFilter = e.target.checked;\n      updateAll();\n    });\n\n    document.getElementById('btnReset').addEventListener('click', () => {\n      if (state.scanTimer) { clearInterval(state.scanTimer); state.scanTimer = null; document.getElementById('btnScan').textContent = '逐层巡检播放'; }\n      state.step = 4; state.mode = 'ai'; state.splitScreen = false; state.showRuler = true;\n      state.depthIdx = 3; state.cavingPct = 12; state.mudLevel = 0.15; state.uvThr = 0.32; state.cavingFilter = true;\n      document.getElementById('chkSplit').checked = false;\n      document.getElementById('chkRuler').checked = true;\n      document.getElementById('rngCaving').value = 12; document.getElementById('outCaving').textContent = '12%';\n      document.getElementById('rngMud').value = 0.15; document.getElementById('outMud').textContent = '0.15';\n      document.getElementById('rngUvThr').value = 0.32; document.getElementById('outUvThr').textContent = '0.32';\n      document.getElementById('chkCavingFilter').checked = true;\n      updateAll();\n    });\n\n    document.getElementById('btnScan').addEventListener('click', () => {\n      const btn = document.getElementById('btnScan');\n      if (state.scanTimer) {\n        clearInterval(state.scanTimer); state.scanTimer = null;\n        btn.textContent = '逐层巡检播放';\n      } else {\n        btn.textContent = '停止巡检';\n        state.scanTimer = setInterval(() => {\n          state.depthIdx = (state.depthIdx + 1) % DEPTH_LAYERS.length;\n          updateAll();\n        }, 1200);\n      }\n    });\n\n    const cvs = document.getElementById('trayCanvas');\n    const tip = document.getElementById('trayTip');\n    cvs.addEventListener('mousemove', e => {\n      const rect = cvs.getBoundingClientRect();\n      const x = (e.clientX - rect.left) * (cvs.width / rect.width);\n      const y = (e.clientY - rect.top) * (cvs.height / rect.height);\n      let hit = -1;\n      for (let i = 0; i < state.chips.length; i++) {\n        const ch = state.chips[i];\n        if (Math.hypot(x - ch.cx, y - ch.cy) <= ch.baseRad + 4) { hit = i; break; }\n      }\n      if (hit !== state.hoverChip) {\n        state.hoverChip = hit;\n        renderTrayCanvas();\n      }\n      if (hit >= 0) {\n        const ch = state.chips[hit];\n        const li = LITHOS[ch.predLitho];\n        tip.innerHTML = `<b>颗粒 #${ch.id}</b> · ${li.name}<br>粒径 ${ch.grainMm.toFixed(2)}mm · UV发光 ${Math.round(ch.uvCover * 100)}%`;\n        tip.style.left = Math.min(cvs.width - 150, x + 12) + 'px';\n        tip.style.top = Math.max(8, y - 34) + 'px';\n        tip.classList.add('show');\n      } else {\n        tip.classList.remove('show');\n      }\n    });\n    cvs.addEventListener('mouseleave', () => {\n      state.hoverChip = -1;\n      tip.classList.remove('show');\n      renderTrayCanvas();\n    });\n    cvs.addEventListener('click', () => {\n      if (state.hoverChip >= 0) {\n        state.selectedChip = state.hoverChip;\n        renderTrayCanvas();\n        renderChipInspector();\n      }\n    });\n  }\n\n  bindEvents();\n  updateAll();\n})();\n","enc":"text","size":40906}]};